(function () {
  'use strict';
  var FILES = [{"name":"demo/aflow.css","mime":"text/css","data":"/* =========================================================\n   AFlow · 算法解剖引擎样式\n   浅色主题，配色与主站令牌一致。三个案例包共用同一份。\n   ========================================================= */\n.af {\n  --af-ink: #242b2e; --af-ink2: #4d565b; --af-ink3: #79828a; --af-ink4: #9ba3a9;\n  --af-line: #e9e4d8; --af-line2: #f0ece1;\n  --af-jade: #2f7d6b; --af-jade-l: #e6f1ec; --af-jade-d: #22604f;\n  --af-clay: #b26a39; --af-red: #b05a51; --af-blue: #41699b;\n  border: 1px solid var(--af-line); border-radius: 12px; background: #fff;\n  padding: 14px 16px 12px; margin-top: 12px;\n}\n\n/* ---- 顶栏 ---- */\n.af-top { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }\n.af-head { min-width: 0; }\n.af-ttl {\n  display: inline-block; font-size: 10px; font-weight: 700; letter-spacing: .1em;\n  color: var(--af-jade); font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  background: var(--af-jade-l); border-radius: 4px; padding: 2px 8px; margin-right: 8px;\n}\n.af-sub { font-size: 12.5px; color: var(--af-ink2); }\n.af-ctrls { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }\n.af-b {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  width: 28px; height: 26px; border-radius: 6px; cursor: pointer;\n  font-size: 12px; line-height: 1; font-family: inherit;\n  display: inline-flex; align-items: center; justify-content: center;\n  transition: all .14s;\n}\n.af-b:hover { border-color: var(--af-jade); color: var(--af-jade-d); background: var(--af-jade-l); }\n.af-play { width: 34px; font-size: 10px; }\n.af-sp {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  border-radius: 6px; height: 26px; font-size: 11px; font-family: inherit; padding: 0 4px; cursor: pointer;\n}\n.af-sp:focus { outline: 2px solid var(--af-jade); outline-offset: 1px; }\n\n/* ---- 阶段轨道 ---- */\n.af-rail {\n  display: flex; gap: 4px; margin-top: 11px; overflow-x: auto; padding-bottom: 2px;\n  scrollbar-width: thin;\n}\n.af-node {\n  flex: 1 1 0; min-width: 96px; text-align: left; cursor: pointer; font-family: inherit;\n  border: 1px solid var(--af-line); background: #fff; border-radius: 7px;\n  padding: 5px 8px 6px; display: block; transition: all .16s; position: relative;\n}\n.af-node:hover { border-color: var(--af-jade); }\n.af-node .af-n {\n  display: inline-block; font-size: 9px; font-weight: 700; color: var(--af-ink4);\n  font-family: ui-monospace, monospace; margin-right: 5px;\n}\n.af-node .af-nm { font-size: 11.5px; color: var(--af-ink2); font-weight: 600; }\n.af-node .af-tg {\n  display: block; font-size: 9px; color: var(--af-ink4); margin-top: 1px;\n  font-family: ui-monospace, monospace; letter-spacing: .01em;\n}\n.af-node.done { border-color: #cfe3da; background: #f7fbf9; }\n.af-node.done .af-n { color: var(--af-jade); }\n.af-node.on { border-color: var(--af-jade); background: var(--af-jade-l); box-shadow: 0 0 0 2px rgba(47,125,107,.1); }\n.af-node.on .af-n { color: var(--af-jade-d); }\n.af-node.on .af-nm { color: var(--af-jade-d); }\n.af-node.on .af-tg { color: var(--af-jade); }\n\n/* ---- 进度条 ---- */\n.af-prog { height: 3px; background: var(--af-line2); border-radius: 2px; margin-top: 8px; overflow: hidden; }\n.af-prog i { display: block; height: 100%; background: var(--af-jade); border-radius: 2px; transition: width .06s linear; }\n\n/* ---- 舞台 ---- */\n.af-stage { margin-top: 10px; }\n.af-stage svg {\n  display: block; width: 100%; height: auto; max-height: 620px;\n  background: #fbfaf6; border: 1px solid var(--af-line); border-radius: 9px;\n}\n\n/* ---- 说明 + 读数 ---- */\n.af-meta { display: grid; grid-template-columns: 1fr 250px; gap: 12px; margin-top: 10px; align-items: start; }\n.af-note {\n  font-size: 12.5px; line-height: 1.72; color: var(--af-ink2);\n  background: #f4f3ef; border-left: 3px solid var(--af-jade); border-radius: 0 5px 5px 0;\n  padding: 8px 12px; min-height: 38px;\n}\n.af-note b { color: var(--af-ink); font-weight: 700; }\n.af-note code, .af-note .mono {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px;\n  background: #fff; border: 1px solid var(--af-line); border-radius: 3px; padding: 0 4px;\n}\n.af-stats { display: flex; flex-wrap: wrap; gap: 5px; align-content: flex-start; }\n.af-stat {\n  background: #fff; border: 1px solid var(--af-line); border-radius: 6px;\n  padding: 4px 9px; min-width: 74px; flex: 1 1 auto;\n}\n.af-stat .k { display: block; font-size: 9.5px; color: var(--af-ink4); letter-spacing: .02em; }\n.af-stat .v {\n  display: block; font-family: ui-monospace, monospace; font-size: 13px;\n  font-weight: 600; color: var(--af-ink); margin-top: 1px;\n}\n.af-stat.t-ok .v { color: var(--af-jade-d); }\n.af-stat.t-warn .v { color: var(--af-clay); }\n.af-stat.t-bad .v { color: var(--af-red); }\n\n.af-count { margin-top: 7px; font-size: 10.5px; color: var(--af-ink4); font-family: ui-monospace, monospace; text-align: right; }\n\n@media (max-width: 860px) {\n  .af-meta { grid-template-columns: 1fr; }\n  .af-node { min-width: 84px; }\n  .af-node .af-nm { font-size: 11px; }\n}\n"},{"name":"demo/aflow.js","mime":"text/javascript","data":"/* =========================================================\n   AFlow · 算法解剖引擎（纯前端，零依赖）\n   ---------------------------------------------------------\n   用途：把「模型算法从输入走到输出」拆成若干可播放的阶段。\n   每个阶段跑的是真实的一段中间计算（不是抽象节点示意），\n   引擎负责：阶段轨道 / 播放控制 / 进度 / 实时读数 / 说明文字。\n\n   两种阶段写法\n   ------------\n   A) SVG 阶段 —— 适合示意图型中间量\n      { name, tag, dur,\n        draw: function (t, g, ctx) {\n          return { svg: '...', stats: [{k,v,tone}], note: '...' };\n        } }\n\n   B) DOM 阶段 —— 适合逐像素 / 逐节点的真实计算动画\n      { name, tag, dur,\n        init: function (host) {          // 只跑一次，构建 DOM\n          return {\n            update: function (t, ctx) {  // 每帧调用，负责重绘\n              return { stats: [...], note: '...' };\n            }\n          };\n        } }\n\n   用法：\n     AFlow.create({\n       mount: document.getElementById('flowMount'),\n       state: {},\n       stages: [ ... ]\n     });\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* ---------------- 配色（浅色主题，与主站令牌一致） ---------------- */\n  var C = {\n    ink: '#242b2e', ink2: '#4d565b', ink3: '#79828a', ink4: '#9ba3a9',\n    line: '#e9e4d8', line2: '#f0ece1', paper: '#fbfaf6', card: '#ffffff',\n    jade: '#2f7d6b', jadeL: '#e6f1ec', jadeD: '#22604f',\n    clay: '#b26a39', clayL: '#f8ecdf',\n    blue: '#41699b', blueL: '#e7eef9',\n    purple: '#7e5a8d', purpleL: '#efe9f4',\n    amber: '#c98a2b', amberL: '#faf3e2',\n    red: '#b05a51', redL: '#f9e9e5',\n    gray: '#79828a', grayL: '#f1f1ee'\n  };\n\n  /* 三栏坐标系：输入 → 算法内部 → 输出。画布 1000×520 */\n  var COLS = [\n    { x: 18, w: 272 },\n    { x: 312, w: 372 },\n    { x: 706, w: 276 }\n  ];\n  var TOP = 30, PANEL_H = 440, RAIL_Y = 484;\n\n  /* ---------------- 绘图 helper ---------------- */\n  var G = {\n    C: C, COLS: COLS, TOP: TOP, PANEL_H: PANEL_H,\n\n    esc: function (s) {\n      return String(s == null ? '' : s)\n        .replace(/&/g, '&amp;').replace(/<\/g, '&lt;').replace(/>/g, '&gt;');\n    },\n    f: function (v, n) {\n      n = (n === undefined) ? 2 : n;\n      if (v === null || v === undefined || !isFinite(v)) return '—';\n      return Number(v).toFixed(n);\n    },\n    rect: function (x, y, w, h, o) {\n      o = o || {};\n      return '<rect x=\"' + x + '\" y=\"' + y + '\" width=\"' + Math.max(0, w) + '\" height=\"' + Math.max(0, h) +\n        '\" rx=\"' + (o.r == null ? 4 : o.r) + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') + '/>';\n    },\n    line: function (x1, y1, x2, y2, o) {\n      o = o || {};\n      return '<line x1=\"' + x1 + '\" y1=\"' + y1 + '\" x2=\"' + x2 + '\" y2=\"' + y2 +\n        '\" stroke=\"' + (o.stroke || C.line) + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') + '/>';\n    },\n    path: function (d, o) {\n      o = o || {};\n      return '<path d=\"' + d + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.5 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') +\n        (o.join ? ' stroke-linejoin=\"' + o.join + '\"' : '') + '/>';\n    },\n    txt: function (x, y, s, o) {\n      o = o || {};\n      var size = o.size == null ? 11 : o.size;\n      var fill = o.fill || C.ink2;\n      var anchor = o.anchor || 'start';\n      var weight = o.weight ? ' font-weight=\"' + o.weight + '\"' : '';\n      var fam = o.mono ? ' font-family=\"ui-monospace,SFMono-Regular,Menlo,Consolas,monospace\"' : '';\n      var extra = (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.ls ? ' letter-spacing=\"' + o.ls + '\"' : '');\n      return '<text x=\"' + x + '\" y=\"' + y + '\" text-anchor=\"' + anchor + '\" font-size=\"' + size +\n        '\" fill=\"' + fill + '\"' + weight + fam + extra + '>' + G.esc(s) + '<\/text>';\n    },\n    circle: function (cx, cy, r, o) {\n      o = o || {};\n      return '<circle cx=\"' + cx + '\" cy=\"' + cy + '\" r=\"' + r + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.2 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') + '/>';\n    },\n    poly: function (pts, o) {\n      o = o || {};\n      var d = '';\n      for (var i = 0; i < pts.length; i++) d += (i ? 'L' : 'M') + pts[i][0].toFixed(1) + ' ' + pts[i][1].toFixed(1) + ' ';\n      return G.path(d + (o.close ? 'Z' : ''), o);\n    },\n    /* 标准三栏面板：全站统一的「输入 / 算法内部 / 输出」视觉语法 */\n    panel: function (ci, title, sub, color, dim) {\n      var c = COLS[ci];\n      var o = G.rect(c.x, TOP, c.w, PANEL_H, {\n        r: 8, fill: '#ffffff', stroke: dim ? '#efece1' : C.line, sw: 1\n      });\n      o += G.rect(c.x, TOP, c.w, 3, { r: 1.5, fill: color || C.line, op: dim ? 0.32 : 1 });\n      o += G.txt(c.x + 13, TOP + 25, title, { size: 12.5, fill: dim ? C.ink3 : C.ink, weight: 700 });\n      if (sub) o += G.txt(c.x + 13, TOP + 41, sub, { size: 10, fill: C.ink4 });\n      o += G.line(c.x, TOP + 50, c.x + c.w, TOP + 50, { stroke: C.line2 });\n      return o;\n    },\n    /* 栏间箭头：标出「数据流向下一层」 */\n    arrow: function (x, y, color, label, sub) {\n      var o = G.path('M' + x + ' ' + (y - 5) + 'L' + (x + 11) + ' ' + y + 'L' + x + ' ' + (y + 5) +\n        'L' + (x + 3) + ' ' + y + 'Z', { fill: color || C.line });\n      if (label) o += G.txt(x - 2, y - 11, label, { size: 9.5, fill: color || C.ink3, anchor: 'middle', weight: 700 });\n      if (sub) o += G.txt(x - 2, y + 18, sub, { size: 8.5, fill: C.ink4, anchor: 'middle' });\n      return o;\n    },\n    /* 数据形态缎带：把「输入张量 → 中间张量 → 输出张量」的形状串成一条 */\n    shapes: function (list, active) {\n      if (!list || !list.length) return '';\n      var o = '', x = 18, w = 964;\n      var n = list.length, pad = 7;\n      var cw = (w - pad * (n - 1)) / n;\n      for (var i = 0; i < n; i++) {\n        var on = (i === active);\n        o += G.rect(x, RAIL_Y, cw, 24, {\n          r: 5, fill: on ? C.jadeL : '#ffffff', stroke: on ? C.jade : C.line, sw: on ? 1.3 : 1\n        });\n        o += G.txt(x + cw / 2, RAIL_Y + 16, list[i], {\n          size: 9.5, anchor: 'middle', mono: true,\n          fill: on ? C.jadeD : C.ink3, weight: on ? 700 : 400\n        });\n        if (i < n - 1) o += G.txt(x + cw + pad / 2, RAIL_Y + 16, '→', { size: 10, fill: C.ink4, anchor: 'middle' });\n        x += cw + pad;\n      }\n      return o;\n    },\n    axes: function (x, y, w, h, o) {\n      o = o || {};\n      var s = G.rect(x, y, w, h, { r: 4, fill: o.fill || '#fdfdfb', stroke: o.stroke || C.line2 });\n      if (o.nx) for (var i = 1; i < o.nx; i++) {\n        s += G.line(x + w * i / o.nx, y, x + w * i / o.nx, y + h, { stroke: C.line2, op: 0.7 });\n      }\n      if (o.ny) for (var j = 1; j < o.ny; j++) {\n        s += G.line(x, y + h * j / o.ny, x + w, y + h * j / o.ny, { stroke: C.line2, op: 0.7 });\n      }\n      return s;\n    }\n  };\n\n  /* ---------------- 引擎 ---------------- */\n  function create(opts) {\n    var mount = opts.mount;\n    if (!mount) return null;\n    var stages = (opts.stages || []).filter(function (s) { return s && (typeof s.draw === 'function' || typeof s.init === 'function'); });\n    if (!stages.length) return null;\n\n    var state = opts.state || {};\n    var idx = 0, t = 0, playing = opts.autoplay !== false, speed = 1;\n    var raf = null, lastTs = 0, dirty = true;\n    var domStage = null, domHandle = null;\n\n    mount.innerHTML =\n      '<div class=\"af\">' +\n      '  <div class=\"af-top\">' +\n      '    <div class=\"af-head\">' +\n      '      <span class=\"af-ttl\">' + G.esc(opts.title || '算法解剖') + '<\/span>' +\n      '      <span class=\"af-sub\">' + G.esc(opts.subtitle || '自动播放：输入怎么一步步变成输出') + '<\/span>' +\n      '    <\/div>' +\n      '    <div class=\"af-ctrls\">' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"prev\" title=\"上一步\">‹<\/button>' +\n      '      <button type=\"button\" class=\"af-b af-play\" data-a=\"play\" title=\"播放/暂停\">❚❚<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"next\" title=\"下一步\">›<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"reset\" title=\"重播\">↺<\/button>' +\n      '      <select class=\"af-sp\" data-a=\"speed\" title=\"速度\">' +\n      '        <option value=\"0.5\">0.5×<\/option><option value=\"1\" selected>1×<\/option>' +\n      '        <option value=\"1.5\">1.5×<\/option><option value=\"2\">2×<\/option>' +\n      '      <\/select>' +\n      '    <\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-rail\"><\/div>' +\n      '  <div class=\"af-prog\"><i><\/i><\/div>' +\n      '  <div class=\"af-stage\"><\/div>' +\n      '  <div class=\"af-meta\">' +\n      '    <div class=\"af-note\"><\/div>' +\n      '    <div class=\"af-stats\"><\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-count\"><\/div>' +\n      '<\/div>';\n\n    var $ = function (sel) { return mount.querySelector(sel); };\n    var stageEl = $('.af-stage');\n    var railEl = $('.af-rail');\n    var progEl = $('.af-prog i');\n    var noteEl = $('.af-note');\n    var statsEl = $('.af-stats');\n    var countEl = $('.af-count');\n    var playBtn = $('[data-a=\"play\"]');\n\n    /* ---- 阶段轨道 ---- */\n    var nodeEls = stages.map(function (s, i) {\n      var b = document.createElement('button');\n      b.type = 'button';\n      b.className = 'af-node';\n      b.innerHTML = '<span class=\"af-n\">' + (i + 1) + '<\/span>' +\n        '<span class=\"af-nm\">' + G.esc(s.name) + '<\/span>' +\n        (s.tag ? '<span class=\"af-tg\">' + G.esc(s.tag) + '<\/span>' : '');\n      b.addEventListener('click', function () { goto(i); });\n      railEl.appendChild(b);\n      return b;\n    });\n\n    function goto(i) {\n      var ni = Math.max(0, Math.min(stages.length - 1, i));\n      if (ni !== idx) { disposeDom(); }\n      idx = ni; t = 0; dirty = true;\n      render(true);\n    }\n\n    /* 精确跳到某阶段的某个进度（0—1）。测试与「定位某一帧」用。 */\n    function seek(i, tt) {\n      goto(i);\n      t = Math.max(0, Math.min(1, tt == null ? 0 : tt));\n      dirty = true;\n      render(true);\n    }\n\n    function disposeDom() {\n      if (domHandle && typeof domHandle.destroy === 'function') {\n        try { domHandle.destroy(); } catch (e) { }\n      }\n      domHandle = null; domStage = null;\n    }\n\n    function totalDur() {\n      var s = 0;\n      for (var i = 0; i < stages.length; i++) s += (stages[i].dur || 2200);\n      return s;\n    }\n\n    function elapsed() {\n      var s = 0;\n      for (var i = 0; i < idx; i++) s += (stages[i].dur || 2200);\n      return s + t * (stages[idx].dur || 2200);\n    }\n\n    function render(force) {\n      if (!dirty && !force) return;\n      dirty = false;\n      var st = stages[idx];\n      var res = {};\n\n      try {\n        if (typeof st.init === 'function') {\n          /* DOM 阶段：init 只在进入该阶段时跑一次 */\n          if (domStage !== idx) {\n            disposeDom();\n            stageEl.innerHTML = '';\n            var host = document.createElement('div');\n            host.className = 'af-dom';\n            stageEl.appendChild(host);\n            domHandle = st.init(host) || {};\n            domStage = idx;\n          }\n          res = domHandle.update ? (domHandle.update(t, { index: idx, stage: st, state: state, api: api }) || {}) : {};\n        } else {\n          res = st.draw(t, G, { index: idx, stage: st, state: state, api: api }) || {};\n          stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\">' +\n            (res.svg || '') + '<\/svg>';\n        }\n      } catch (err) {\n        disposeDom();\n        stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\">' +\n          G.panel(1, '这一段出了点问题', String(err && err.message || err), C.red) +\n          G.txt(500, 260, '（算法计算中断，其余阶段不受影响）', { size: 11, fill: C.ink3, anchor: 'middle' }) +\n          '<\/svg>';\n        res = {\n          stats: [],\n          note: '<b style=\"color:' + C.red + '\">绘制失败：<\/b>' + G.esc(String(err && err.message || err))\n        };\n      }\n\n      /* 统计格 */\n      var stats = res.stats || [];\n      var h = '';\n      for (var i = 0; i < stats.length; i++) {\n        var s0 = stats[i];\n        h += '<div class=\"af-stat' + (s0.tone ? ' t-' + s0.tone : '') + '\">' +\n          '<span class=\"k\">' + G.esc(s0.k) + '<\/span><b class=\"v\">' + G.esc(s0.v) + '<\/b><\/div>';\n      }\n      statsEl.innerHTML = h;\n\n      noteEl.innerHTML = res.note || '';\n\n      for (var j = 0; j < nodeEls.length; j++) {\n        nodeEls[j].className = 'af-node' + (j === idx ? ' on' : (j < idx ? ' done' : ''));\n      }\n      countEl.textContent = '第 ' + (idx + 1) + ' / ' + stages.length + ' 步 · ' + (st.name || '');\n\n      progEl.style.width = (elapsed() / totalDur() * 100).toFixed(2) + '%';\n\n      playBtn.textContent = playing ? '❚❚' : '▶';\n      playBtn.title = playing ? '暂停' : '播放';\n    }\n\n    /* ---- 播放循环 ---- */\n    function tick(ts) {\n      raf = requestAnimationFrame(tick);\n      if (!lastTs) lastTs = ts;\n      var dt = Math.min(120, ts - lastTs);\n      lastTs = ts;\n      if (playing) {\n        var dur = stages[idx].dur || 2200;\n        t += (dt * speed) / dur;\n        if (t >= 1) {\n          if (idx < stages.length - 1) { disposeDom(); idx++; t = 0; }\n          else if (opts.loop !== false) { disposeDom(); idx = 0; t = 0; }\n          else { t = 1; playing = false; }\n        }\n        dirty = true;\n      }\n      if (dirty) render();\n    }\n\n    /* ---- 控制 ---- */\n    mount.querySelectorAll('.af-b, .af-sp').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var a = btn.getAttribute('data-a');\n        if (a === 'play') { playing = !playing; lastTs = 0; dirty = true; render(); }\n        else if (a === 'reset') { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); }\n        else if (a === 'prev') { if (t > 0.12) { t = 0; } else { goto(idx - 1); } dirty = true; render(); }\n        else if (a === 'next') { goto(idx + 1); }\n        else if (a === 'speed') { speed = parseFloat(btn.value) || 1; }\n      });\n    });\n    var sp = mount.querySelector('[data-a=\"speed\"]');\n    if (sp) sp.addEventListener('change', function () { speed = parseFloat(this.value) || 1; });\n\n    /* ---- 对外 API ---- */\n    var api = {\n      goto: goto,\n      seek: seek,\n      restart: function () { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); },\n      play: function () { playing = true; dirty = true; render(); },\n      pause: function () { playing = false; dirty = true; render(); },\n      refresh: function () { dirty = true; render(); },\n      get index() { return idx; },\n      setData: function (k, v) { state[k] = v; dirty = true; },\n      getData: function (k) { return state[k]; },\n      destroy: function () {\n        if (raf) cancelAnimationFrame(raf);\n        raf = null;\n        disposeDom();\n        mount.innerHTML = '';\n      }\n    };\n    if (opts.onReady) opts.onReady(api);\n\n    render(true);\n    raf = requestAnimationFrame(tick);\n    return api;\n  }\n\n  global.AFlow = { create: create, C: C, G: G, COLS: COLS };\n})(typeof window !== 'undefined' ? window : this);\n"},{"name":"demo/aiq.css","mime":"text/css","data":"/* =========================================================\n   AI 三问 · 可运行示范页通用区块\n   ---------------------------------------------------------\n   01 为什么（传统做法 vs AI 做法的同一段数据对照）\n   02 是什么（把业务对象翻译成算法可处理的形式）\n   03 怎样实现（五步工程路线，可跳到下方逐帧解剖）\n   依赖各包 demo.css 里的 --jade / --clay / --blue / --ink*\n   ========================================================= */\n\n.aiq {\n  margin: 0 0 18px; padding: 15px 18px 16px;\n  background: linear-gradient(180deg, #fbfaf6 0%, #ffffff 52%);\n  border: 1px solid var(--line, #e9e4d8); border-radius: 12px;\n}\n.aiq-top { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 12px; }\n.aiq-chip {\n  flex: none; font-size: 10px; font-weight: 700; letter-spacing: .12em;\n  color: var(--jade, #2f7d6b); background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  border-radius: 999px; padding: 3px 9px; margin-top: 1px;\n}\n.aiq-lede { margin: 0; font-size: 13px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-lede b { color: var(--ink, #242b2e); }\n\n.aiq-grid { display: grid; grid-template-columns: 1.32fr 1fr 1fr; gap: 11px; }\n@media (max-width: 1040px) and (min-width: 760px) {\n  .aiq-grid { grid-template-columns: 1fr 1fr; grid-template-areas: \"a a\" \"b c\"; }\n  .aiq-card.q1 { grid-area: a; }\n  .aiq-card.q2 { grid-area: b; }\n  .aiq-card.q3 { grid-area: c; }\n}\n@media (max-width: 759px) { .aiq-grid { grid-template-columns: 1fr; } }\n.aiq-foot { margin: auto 0 0; padding-top: 2px; font-size: 10.5px; line-height: 1.5; color: var(--ink-4, #9ba3a9); }\n\n.aiq-card {\n  display: flex; flex-direction: column; gap: 9px;\n  border: 1px solid var(--line, #e9e4d8); border-radius: 10px;\n  background: #fff; padding: 11px 12px 11px;\n}\n.aiq-hd {\n  display: flex; align-items: center; gap: 7px;\n  padding-bottom: 8px; border-bottom: 1px dashed var(--line, #e9e4d8);\n}\n.aiq-hd .n {\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 10.5px; font-weight: 700; color: #fff;\n  border-radius: 5px; padding: 2px 6px; line-height: 1.5;\n}\n.aiq-hd > div { display: flex; align-items: baseline; gap: 4px; }\n.aiq-hd b { font-size: 14px; color: var(--ink, #242b2e); letter-spacing: .01em; }\n.aiq-hd em {\n  font-style: normal; font-size: 9px; letter-spacing: .16em; color: var(--ink-4, #9ba3a9);\n}\n.aiq-card.q1 .aiq-hd .n { background: var(--clay, #b26a39); }\n.aiq-card.q2 .aiq-hd .n { background: var(--blue, #41699b); }\n.aiq-card.q3 .aiq-hd .n { background: var(--jade, #2f7d6b); }\n\n/* ---------- 01 为什么：曲线对照 ---------- */\n.aiq-switch {\n  display: inline-flex; align-self: flex-start; gap: 2px; padding: 2px;\n  background: var(--card, #fbfaf6); border: 1px solid var(--line, #e9e4d8); border-radius: 999px;\n}\n.aiq-switch button {\n  font: inherit; font-size: 11.5px; line-height: 1.5; cursor: pointer;\n  border: 0; background: transparent; color: var(--ink-3, #79828a);\n  padding: 3px 11px; border-radius: 999px; transition: all .15s;\n}\n.aiq-switch button:hover { color: var(--ink, #242b2e); }\n.aiq-switch button.on {\n  background: #fff; color: var(--ink, #242b2e); font-weight: 600;\n  box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n}\n.aiq-fig { margin: 1px 0 0; }\n.aiq-fig svg { display: block; width: 100%; height: auto; }\n\n.aiq-nums {\n  display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;\n  margin: 0; padding: 0; list-style: none;\n}\n.aiq-nums li {\n  background: var(--card, #fbfaf6); border: 1px solid #efeadf; border-radius: 7px;\n  padding: 5px 6px 6px; text-align: center;\n}\n.aiq-nums b {\n  display: block; font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 14.5px; line-height: 1.25; color: var(--ink-2, #4d565b);\n  font-variant-numeric: tabular-nums; transition: color .2s;\n}\n.aiq-nums span { display: block; font-size: 10px; color: var(--ink-3, #79828a); line-height: 1.35; margin-top: 2px; }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"good\"] b { color: var(--jade, #2f7d6b); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"bad\"] b { color: var(--clay, #b26a39); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"neut\"] b { color: var(--ink, #242b2e); }\n\n.aiq-note { margin: 0; font-size: 11.5px; line-height: 1.62; color: var(--ink-3, #79828a); }\n.aiq-note b { color: var(--ink-2, #4d565b); }\n.aiq-note .hl-bad { color: var(--clay, #b26a39); font-weight: 600; }\n.aiq-note .hl-good { color: var(--jade, #2f7d6b); font-weight: 600; }\n\n/* ---------- 02 是什么：翻译管线 + 式子 ---------- */\n.aiq-say { margin: 0; font-size: 12.5px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-say b { color: var(--ink, #242b2e); }\n.aiq-pipe { display: flex; flex-direction: column; }\n.aiq-pipe .p {\n  position: relative; padding: 5px 8px 5px 27px; border-radius: 6px;\n  background: var(--card, #fbfaf6); font-size: 11.5px; line-height: 1.5; color: var(--ink-3, #79828a);\n}\n.aiq-pipe .p i {\n  position: absolute; left: 8px; top: 6px; font-style: normal;\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px;\n  color: var(--blue, #41699b); font-weight: 700; letter-spacing: .02em;\n}\n.aiq-pipe .p b { color: var(--ink-2, #4d565b); font-weight: 600; }\n.aiq-pipe .ar { display: grid; place-items: center; height: 11px; }\n.aiq-pipe .ar::before {\n  content: \"\"; width: 1px; height: 7px; background: #ddd6c8;\n  box-shadow: 0 7px 0 -2px #ddd6c8;\n}\n.aiq-eq {\n  margin: 0; padding: 6px 9px; border-radius: 7px;\n  background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 11px; line-height: 1.8; color: #1f5f4d;\n  overflow-x: auto; white-space: nowrap;\n}\n.aiq-eq em { font-style: normal; color: #5f8f80; font-size: 10px; }\n.aiq-fit { margin: 0; padding: 0; list-style: none; font-size: 11.5px; line-height: 1.56; color: var(--ink-2, #4d565b); }\n.aiq-fit li { position: relative; padding-left: 15px; }\n.aiq-fit li + li { margin-top: 2px; }\n.aiq-fit li i { position: absolute; left: 0; top: 0; font-style: normal; font-weight: 700; }\n.aiq-fit .y i { color: var(--jade, #2f7d6b); }\n.aiq-fit .n i { color: var(--clay, #b26a39); }\n\n/* ---------- 03 怎样实现：五步 + 跳转 ---------- */\n.aiq-steps { margin: 0; padding: 0; list-style: none; counter-reset: aiqs; }\n.aiq-steps li {\n  position: relative; padding-left: 20px;\n  font-size: 11.5px; line-height: 1.55; color: var(--ink-2, #4d565b);\n}\n.aiq-steps li + li { margin-top: 5px; }\n.aiq-steps li::before {\n  counter-increment: aiqs; content: counter(aiqs);\n  position: absolute; left: 0; top: 1px; width: 14px; height: 14px;\n  border-radius: 50%; background: var(--jade-bg, #e6f1ec); color: var(--jade, #2f7d6b);\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px; font-weight: 700;\n  display: grid; place-items: center;\n}\n.aiq-steps li b { color: var(--ink, #242b2e); font-weight: 600; }\n.aiq-steps li code {\n  font-family: ui-monospace, Consolas, monospace; font-size: 10px;\n  background: #f3f0e8; border-radius: 3px; padding: 0 3px; color: #5c666b;\n}\n.aiq-jump {\n  margin-top: auto; padding-top: 8px; border-top: 1px dashed var(--line, #e9e4d8);\n  display: flex; align-items: center; justify-content: space-between; gap: 8px;\n}\n.aiq-jump span { font-size: 11px; color: var(--ink-4, #9ba3a9); }\n.aiq-jump a {\n  font-size: 11.5px; font-weight: 600; color: var(--jade, #2f7d6b);\n  text-decoration: none; white-space: nowrap;\n}\n.aiq-jump a:hover { color: #1f5f4d; text-decoration: underline; }\n\n/* 折叠态的三问（窄屏或用户收起时） */\n@media (max-width: 720px) {\n  .aiq { padding: 13px 12px 14px; }\n  .aiq-top { flex-direction: column; gap: 6px; }\n  .aiq-nums b { font-size: 13.5px; }\n}\n\n/* ---------- 03 卡内的踩坑提示 ---------- */\n.aiq-warn {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: var(--clay-bg, #f7ece2); border: 1px solid #eed9c6;\n  font-size: 11.5px; line-height: 1.6; color: #8a4f28;\n}\n.aiq-warn b { display: block; font-size: 10px; letter-spacing: .06em; color: var(--clay, #b26a39); margin-bottom: 2px; }\n\n/* ---------- 01 卡的对比表（没有可画的数字时用） ---------- */\n.aiq-tbl { width: 100%; border-collapse: collapse; font-size: 11.5px; }\n.aiq-tbl th {\n  font-size: 9.5px; font-weight: 600; color: var(--ink-4, #9ba3a9);\n  text-align: left; padding: 0 6px 5px; border-bottom: 1px solid var(--line, #e9e4d8);\n  letter-spacing: .02em;\n}\n.aiq-tbl th:first-child { padding-left: 0; }\n.aiq-tbl th:nth-child(2) { color: #8a9099; }\n.aiq-tbl th:nth-child(3) { color: var(--jade, #2f7d6b); }\n.aiq-tbl td {\n  padding: 5px 6px; border-bottom: 1px dashed #f2eee4;\n  color: var(--ink-2, #4d565b); line-height: 1.45; vertical-align: top;\n}\n.aiq-tbl td:first-child { padding-left: 0; color: var(--ink-3, #79828a); font-size: 11px; white-space: nowrap; }\n.aiq-tbl td:nth-child(2) { color: #7b838a; }\n.aiq-tbl td:nth-child(3) { color: #1f5f4d; font-weight: 500; }\n.aiq-tbl tr:last-child td { border-bottom: 0; }\n\n/* ---------- 01 卡的「代价」补充（填满短卡，也把边界说清） ---------- */\n.aiq-cost {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: #f4f2ea; border: 1px solid #e8e3d5;\n  font-size: 11.5px; line-height: 1.6; color: #5f676c;\n}\n.aiq-cost b { display: block; font-size: 10px; letter-spacing: .06em; color: #8a9099; margin-bottom: 2px; }\n"},{"name":"demo/aiq.js","mime":"text/javascript","data":"/* =========================================================\n   AI 三问 · 交互（只服务 01「为什么」卡的曲线对照）\n   ---------------------------------------------------------\n   同一段数据、同一条劣化曲线，切换「传统做法 / AI 做法」：\n   传统只在越过阈值那一刻报警；AI 在曲线还落在正常区间时就\n   从「偏离自身基线」的趋势里看出苗头。图上同时给出两处标记、\n   提前量与三个指标数字。\n   无依赖，data-* 配置，多实例安全。\n   ========================================================= */\n(function () {\n  'use strict';\n  var NS = 'http://www.w3.org/2000/svg';\n\n  function mk(name, attrs) {\n    var e = document.createElementNS(NS, name);\n    for (var k in attrs) if (attrs.hasOwnProperty(k)) e.setAttribute(k, attrs[k]);\n    return e;\n  }\n  function txt(s, x, y, o) {\n    var t = mk('text', {\n      x: x, y: y,\n      'font-size': (o && o.size) || 9.5,\n      fill: (o && o.fill) || '#79828a',\n      'text-anchor': (o && o.anchor) || 'start',\n      'font-family': 'ui-monospace, \"SF Mono\", Consolas, monospace',\n      'font-weight': (o && o.weight) || 400\n    });\n    t.textContent = s;\n    return t;\n  }\n\n  /* 曲线：t∈[0,100] → 归一化高度 v∈[0,1]（1=顶部） */\n  function valAt(t, shape, onset) {\n    var a;\n    if (t <= onset) a = 0.295 + 0.095 * (t / Math.max(1, onset));\n    else a = 0.39 + 0.55 * Math.pow((t - onset) / (100 - onset), 1.55);\n    return shape === 'fall' ? 1 - a : a;\n  }\n\n  var W = 420, H = 150, L = 30, R = 10, T = 12, B = 32;\n  function xOf(t) { return L + t / 100 * (W - L - R); }\n  function yOf(v) { return (H - B) - v * ((H - B) - T); }\n\n  /* 条形对比：同一批井/同一批任务，旧做法与新做法的指标代差 */\n  function drawBar(box, mode, cfg) {\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var rows = cfg.rows;\n    var W2 = 372, H2 = 150, TOP = 14, RH = 40, LAB = 92, BARX = 92, BARW = 186;\n    var svg = mk('svg', { viewBox: '0 0 ' + W2 + ' ' + H2, role: 'img' });\n    svg.setAttribute('aria-label', '旧做法与新做法的指标对比');\n\n    var i, r, oldOn = mode === 'old';\n    for (i = 0; i < rows.length; i++) {\n      r = rows[i];\n      var y = TOP + i * RH;\n      svg.appendChild(txt(r[0], 2, y + 11, { size: 10, fill: '#4d565b' }));\n      if (r[4]) svg.appendChild(txt(r[4], 2, y + 24, { size: 8.5, fill: '#9ba3a9' }));\n\n      /* 行首两枚色条：旧 / 新 */\n      svg.appendChild(mk('rect', { x: 0, y: y + 5, width: 2, height: 9, fill: '#8a9099', opacity: oldOn ? 0.9 : 0.25 }));\n      svg.appendChild(mk('rect', { x: 0, y: y + 20, width: 2, height: 9, fill: '#2f7d6b', opacity: oldOn ? 0.25 : 0.9 }));\n\n      /* 纯文本行（无数字可画条） */\n      if (!r[5]) {\n        svg.appendChild(txt(r[1], BARX, y + 12, { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 600 : 400 }));\n        svg.appendChild(txt(r[2], BARX, y + 27, { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 600 }));\n        continue;\n      }\n\n      /* 每行按自身量级归一：不同指标量纲不同，跨行比较没有意义 */\n      var rmax = Math.max(r[1], r[2]) || 1;\n      var wOld = Math.max(2, r[1] / rmax * BARW), wNew = Math.max(2, r[2] / rmax * BARW);\n      var unit = r[3] === '%' ? '%' : (r[3] ? ' ' + r[3] : '');\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 4, width: wOld, height: 9, rx: 2, fill: '#8a9099', opacity: oldOn ? 0.85 : 0.22 }));\n      svg.appendChild(txt(fmt(r[1]) + unit, BARX + BARW + 8, y + 12,\n        { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 700 : 400 }));\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 19, width: wNew, height: 9, rx: 2, fill: '#2f7d6b', opacity: oldOn ? 0.22 : 0.88 }));\n      svg.appendChild(txt(fmt(r[2]) + unit, BARX + BARW + 8, y + 27,\n        { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 700 }));\n    }\n\n    /* 图例 */\n    svg.appendChild(mk('rect', { x: BARX, y: H2 - 9, width: 8, height: 3, fill: '#8a9099', opacity: 0.85 }));\n    svg.appendChild(txt('旧做法', BARX + 12, H2 - 4, { size: 8.5, fill: '#79828a' }));\n    svg.appendChild(mk('rect', { x: BARX + 52, y: H2 - 9, width: 8, height: 3, fill: '#2f7d6b', opacity: 0.88 }));\n    svg.appendChild(txt('新做法', BARX + 64, H2 - 4, { size: 8.5, fill: '#79828a' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n  function fmt(v) {\n    var n = Number(v);\n    if (!isFinite(n)) return String(v);\n    return Math.abs(n) >= 100 ? n.toFixed(0) : (Math.abs(n) >= 10 ? n.toFixed(n % 1 ? 1 : 0) : n.toFixed(n % 1 ? 1 : 0));\n  }\n\n  function draw(box, mode, cfg) {\n    if (cfg.kind === 'bar') { drawBar(box, mode, cfg); return; }\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var svg = mk('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img' });\n    svg.setAttribute('aria-label', '传统做法与 AI 做法的检出时机对比');\n\n    /* 网格 */\n    for (var g = 1; g <= 3; g++) {\n      svg.appendChild(mk('line', {\n        x1: L, y1: yOf(0.24 * g), x2: W - R, y2: yOf(0.24 * g),\n        stroke: '#f1ede2', 'stroke-width': 1\n      }));\n    }\n\n    /* 正常区间带 */\n    var lo = cfg.bandLo, hi = cfg.bandHi;\n    svg.appendChild(mk('rect', {\n      x: L, y: yOf(hi), width: W - L - R, height: Math.max(2, yOf(lo) - yOf(hi)),\n      fill: '#2f7d6b', opacity: 0.07\n    }));\n    svg.appendChild(txt('正常区间', W - R - 3, yOf(hi) + 9, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    /* 报警阈值 */\n    svg.appendChild(mk('line', {\n      x1: L, y1: yOf(cfg.thr), x2: W - R, y2: yOf(cfg.thr),\n      stroke: '#b26a39', 'stroke-width': 1.1, 'stroke-dasharray': '4 3', opacity: 0.6\n    }));\n    svg.appendChild(txt('阈值 θ', W - R - 3, yOf(cfg.thr) - 4, { anchor: 'end', size: 8.5, fill: '#b26a39' }));\n\n    /* 曲线 */\n    var d = '', i, v;\n    for (i = 0; i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      d += (i ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: d, fill: 'none', stroke: '#4d565b', 'stroke-width': 1.7,\n      'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 劣化起点 */\n    svg.appendChild(mk('line', {\n      x1: xOf(cfg.onset), y1: yOf(cfg.thr) - 2, x2: xOf(cfg.onset), y2: yOf(0.06),\n      stroke: '#cfc9bb', 'stroke-width': 1, 'stroke-dasharray': '2 3'\n    }));\n\n    /* 从判定点起，曲线高亮 */\n    var from = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var dd = '';\n    for (i = Math.round(from); i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      dd += (dd ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: dd, fill: 'none',\n      stroke: mode === 'new' ? '#2f7d6b' : '#b26a39',\n      'stroke-width': 2.6, 'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 底部时间轴上的「提前量」量尺 */\n    var yB = H - 15;\n    if (mode === 'new' && cfg.newAt < cfg.oldAt) {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.newAt), y1: yB, x2: xOf(cfg.oldAt), y2: yB,\n        stroke: '#2f7d6b', 'stroke-width': 2.4, opacity: 0.3, 'stroke-linecap': 'round'\n      }));\n      [cfg.newAt, cfg.oldAt].forEach(function (t) {\n        svg.appendChild(mk('line', {\n          x1: xOf(t), y1: yB - 3.5, x2: xOf(t), y2: yB + 3.5,\n          stroke: '#2f7d6b', 'stroke-width': 1.2\n        }));\n      });\n      svg.appendChild(txt('提前 ' + cfg.days + ' 天', (xOf(cfg.newAt) + xOf(cfg.oldAt)) / 2, yB - 5,\n        { anchor: 'middle', size: 9, fill: '#2f7d6b', weight: 600 }));\n    } else {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.oldAt), y1: yB, x2: W - R, y2: yB,\n        stroke: '#b26a39', 'stroke-width': 2.4, opacity: 0.28, 'stroke-linecap': 'round'\n      }));\n      svg.appendChild(txt('这段没有任何预警', W - R - 3, yB - 5,\n        { anchor: 'end', size: 9, fill: '#b26a39', weight: 600 }));\n    }\n\n    /* 判定点 */\n    var tx = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var px = xOf(tx), py = yOf(valAt(tx, cfg.shape, cfg.onset));\n    var col = mode === 'new' ? '#2f7d6b' : '#b26a39';\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 6.5, fill: col, opacity: 0.15 }));\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 3.2, fill: col, stroke: '#fff', 'stroke-width': 1.3 }));\n\n    /* 标签固定在左上角，用细引线指到判定点：两种模式切换时位置不跳，便于对比 */\n    var label = mode === 'new' ? '这里就预警' : '越限才发现';\n    var tw = label.length * 9 + 11, th = 15;\n    var tX = L + 3, tY = T + 1;\n    svg.appendChild(mk('line', {\n      x1: tX + tw / 2, y1: tY + th, x2: px, y2: py - 5,\n      stroke: col, 'stroke-width': 0.8, 'stroke-dasharray': '2 3', opacity: 0.45\n    }));\n    svg.appendChild(mk('rect', {\n      x: tX, y: tY, width: tw, height: th, rx: 3.5,\n      fill: '#fffdf7', stroke: col, 'stroke-width': 0.8, 'stroke-opacity': 0.4\n    }));\n    svg.appendChild(txt(label, tX + 6, tY + 11, { size: 9, fill: col, weight: 600 }));\n\n    /* 轴与单位 */\n    svg.appendChild(txt('时间 →', L, H - 3, { size: 8.5, fill: '#9ba3a9' }));\n    svg.appendChild(txt(cfg.unit, W - R, T + 2, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n\n  function init(box) {\n    var cfg = {\n      shape: box.getAttribute('data-shape') || 'rise',\n      unit: box.getAttribute('data-unit') || '',\n      onset: parseFloat(box.getAttribute('data-onset')) || 55,\n      thr: parseFloat(box.getAttribute('data-thr')) || 0.72,\n      oldAt: parseFloat(box.getAttribute('data-old-at')) || 88,\n      newAt: parseFloat(box.getAttribute('data-new-at')) || 60,\n      days: box.getAttribute('data-days') || '',\n      kind: box.getAttribute('data-kind') || 'trend',\n      rows: (box.getAttribute('data-rows') || '').split(';').filter(function (x) { return x.trim(); }).map(function (x) {\n        var p = x.split('|');\n        var num = isFinite(parseFloat(p[1])) && isFinite(parseFloat(p[2]));\n        return [p[0] || '', num ? parseFloat(p[1]) : (p[1] || ''), num ? parseFloat(p[2]) : (p[2] || ''), p[3] || '', p[4] || '', num];\n      }),\n      bandLo: parseFloat(box.getAttribute('data-band-lo')) || 0.26,\n      bandHi: parseFloat(box.getAttribute('data-band-hi')) || 0.46\n    };\n    var btns = box.querySelectorAll('.aiq-switch button');\n    var nums = box.querySelectorAll('.aiq-nums b[data-old]');\n    var notes = box.querySelectorAll('.aiq-note [data-v]');\n\n    function set(mode) {\n      box.setAttribute('data-mode', mode);\n      [].forEach.call(btns, function (b) { b.classList.toggle('on', b.getAttribute('data-v') === mode); });\n      [].forEach.call(nums, function (n) {\n        var v = n.getAttribute('data-' + (mode === 'old' ? 'old' : 'new'));\n        if (v != null && v !== '') n.textContent = v;\n      });\n      [].forEach.call(notes, function (n) { n.hidden = n.getAttribute('data-v') !== mode; });\n      draw(box, mode, cfg);\n    }\n\n    if (!btns.length) { set('new'); return; }\n    [].forEach.call(btns, function (b) {\n      b.addEventListener('click', function () { set(b.getAttribute('data-v')); });\n    });\n    set('old');\n  }\n\n  function boot() {\n    [].forEach.call(document.querySelectorAll('[data-aiq]'), init);\n  }\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);\n  else boot();\n})();\n"},{"name":"demo/demo.css","mime":"text/css","data":"/* =========================================================\n   地质剖面遥感解译 · 示范页样式（整页模式，沙箱 iframe）\n   浅色主题：全部使用设计令牌 / 低饱和浅色 hex\n   ========================================================= */\n:root {\n  --jade: #2f7d6b;\n  --jade-bg: #e6f1ec;\n  --clay: #b26a39;\n  --clay-bg: #f7ece2;\n  --blue: #41699b;\n  --blue-bg: #e7eef9;\n  --ink: #242b2e;\n  --ink-2: #4d565b;\n  --ink-3: #79828a;\n  --ink-4: #9ba3a9;\n  --line: #e9e4d8;\n  --card: #fbfaf6;\n  --bg: #faf9f4;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 20px 22px 26px;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14.5px/1.7 -apple-system, \"Segoe UI\", \"Microsoft YaHei\", system-ui, sans-serif;\n}\n\n/* ---------- 头部 ---------- */\n.hd { margin-bottom: 18px; }\n.kicker { font-size: 10.5px; letter-spacing: .14em; color: var(--jade); font-weight: 700; }\n.hd h1 { margin: 4px 0 6px; font-size: 21px; color: var(--ink); }\n.hd .sub { margin: 0; color: var(--ink-3); font-size: 13.5px; }\n\n/* ---------- 区块 ---------- */\n.sec {\n  margin-bottom: 26px; padding: 18px 20px;\n  background: var(--card); border: 1px solid var(--line); border-radius: 12px;\n}\n.sec-hd { margin-bottom: 12px; }\n.sec-no { font-size: 10.5px; letter-spacing: .12em; color: var(--ink-4); font-weight: 700; text-transform: uppercase; }\n.sec-hd h2 { margin: 3px 0 6px; font-size: 17px; color: var(--ink); }\n.sec-hd .leadline { margin: 0; color: var(--ink-3); font-size: 13px; }\n.sec-hd .leadline b { color: var(--ink); }\n\n/* ---------- 图例 ---------- */\n.legend { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: 8px 0 4px; }\n.legend .lg { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: var(--ink-2); }\n.legend .lg i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }\n\n/* ---------- 控件 ---------- */\n.ctl { display: flex; flex-wrap: wrap; gap: 14px 24px; align-items: center; margin-bottom: 12px; padding: 10px 12px; background: var(--bg); border: 1px solid var(--line); border-radius: 10px; }\n.ctl .btns { display: flex; flex-wrap: wrap; gap: 6px; }\n.ctl .btns button { font: inherit; font-size: 12.5px; padding: 5px 12px; border-radius: 8px; border: 1px solid var(--line); background: #fff; color: var(--ink-2); cursor: pointer; }\n.ctl .btns button.on, .ctl .btns button:hover { background: var(--jade); color: #fff; border-color: var(--jade); }\n.ctl .sl { display: flex; flex-direction: column; gap: 3px; min-width: 180px; }\n.ctl .sl label { font-size: 12.5px; color: var(--ink-2); display: flex; justify-content: space-between; align-items: center; }\n.ctl .sl output { font-family: ui-monospace, monospace; font-size: 13px; color: var(--jade); font-weight: 600; }\n.ctl input[type=range] { width: 100%; accent-color: var(--jade); }\n\n/* ---------- SVG 图 ---------- */\n.chart-wrap { width: 100%; }\n.chart-wrap svg { width: 100%; height: auto; display: block; border: 1px solid var(--line); border-radius: 8px; background: #fff; }\n.fg { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.fg .cap { font-size: 12px; color: var(--ink-3); text-align: center; margin-top: 6px; }\n@media (max-width:720px){ .fg { grid-template-columns: 1fr; } }\n\n/* ---------- 结果读数行 ---------- */\n.rrow { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; }\n.ro { flex: 1; min-width: 130px; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }\n.ro .k { display: block; font-size: 11px; color: var(--ink-4); margin-bottom: 2px; }\n.ro b { font-size: 15px; color: var(--ink); }\n.ro b.good { color: var(--jade); }\n.ro b.warn { color: var(--clay); }\n\n/* ---------- 提示 / 折叠 ---------- */\n.tip { margin: 10px 0 0; font-size: 12.5px; color: var(--ink-3); background: var(--jade-bg); border-radius: 8px; padding: 8px 12px; }\n.details { margin-top: 12px; }\n.details summary { cursor: pointer; font-size: 13px; color: var(--jade); font-weight: 600; }\n\n/* 算法解剖引擎在 aflow.css 里；AI 三问在 aiq.css 里 */\n"},{"name":"demo/demo.js","mime":"text/javascript","data":"/* =========================================================\n   钻具失效预测 · 示范脚本（整页模式，运行在沙箱 iframe 里）\n   ---------------------------------------------------------\n   三屏：\n   屏 1  疲劳累积：振动/扭矩 → 物理损伤\n   屏 2  剩余寿命预测：损伤特征 → RUL 混合预测\n   屏 3  起钻建议：失效窗口 + 起钻检查回流\n   所有计算都在浏览器里完成，纯前端。\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* =====================================================\n     纯模型层（Node 可 require 做单测；浏览器里继续往下走）\n     ===================================================== */\n  var Model = (function () {\n\n    function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n    function mulberry32(a) {\n      return function () {\n        a |= 0; a = a + 0x6D2B79F5 | 0;\n        var t = Math.imul(a ^ a >>> 15, 1 | a);\n        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\n        return ((t ^ t >>> 14) >>> 0) / 4294967296;\n      };\n    }\n\n    var MODES = ['正常', '振动', '冲击'];\n\n    /* -----------------------------------------------------\n       合成振动/扭矩时序\n       n 采样点，含工况段（mode）。返回 { n, vib:[], tor:[], mode:[] }\n       ----------------------------------------------------- */\n    function genVibration(n, seed) {\n      var rnd = mulberry32(seed || 20261141);\n      var vib = new Float64Array(n), tor = new Float64Array(n), mode = new Int8Array(n);\n      for (var i = 0; i < n; i++) {\n        /* 工况按段切换 */\n        var m;\n        if (i < n * 0.3) m = 0; else if (i < n * 0.55) m = 1; else if (i < n * 0.75) m = 2; else m = 1;\n        mode[i] = m;\n        var vibBase = m === 0 ? 0.15 : m === 1 ? 0.4 : 0.8;\n        var vibAmp = m === 0 ? 0.08 : m === 1 ? 0.15 : 0.25;\n        vib[i] = clamp(vibBase + Math.sin(i * 0.08) * vibAmp * 0.6 + (rnd() - 0.5) * vibAmp * 2, 0, 1.4);\n        tor[i] = clamp(8 + Math.sin(i * 0.05) * 1.5 + (rnd() - 0.5) * 1.2, 3, 15);\n      }\n      return { n: n, vib: vib, tor: tor, mode: mode };\n    }\n\n    /* -----------------------------------------------------\n       疲劳累积（Miner 线性损伤）\n       从振动幅值累加损伤。返回 { damage: Float64Array(0→1), cum, failPoint }\n       ----------------------------------------------------- */\n    function fatigueAccum(vib, n, scale) {\n      var damage = new Float64Array(n);\n      var cum = 0;\n      var failPoint = -1;\n      for (var i = 0; i < n; i++) {\n        var amp = vib[i];\n        /* 损伤速率 ∝ 幅值^2，越接近失效越快 */\n        var rate = (amp * amp) * (0.005 + cum * 0.08) * (scale || 1);\n        cum += rate;\n        cum = Math.min(cum, 1.1);\n        damage[i] = cum;\n        if (failPoint < 0 && cum >= 1) failPoint = i;\n      }\n      return { damage: damage, cum: cum, failPoint: failPoint };\n    }\n\n    /* -----------------------------------------------------\n       剩余寿命预测（混合建模）\n       mode 0 纯时序 1 纯物理 2 混合。返回 { rul: Float64Array, err, method }\n       ----------------------------------------------------- */\n    function rulPredict(damage, mode, n, scale) {\n      var rul = new Float64Array(n);\n      var err = 0;\n      for (var i = 0; i < n; i++) {\n        var d = damage[i];\n        /* 真实剩余寿命 = 1 - d */\n        var trueRul = Math.max(0, (1 - d)) * (scale || 100);\n        var predRul;\n        if (mode === 0) {\n          /* 纯时序：只看当前损伤增量，无物理约束，漂移 */\n          var slope = i > 0 ? Math.max(0, d - damage[Math.max(0, i - 1)]) : 0.002;\n          predRul = (1 - d) / (slope + 0.005) * (scale || 100) * 0.7;\n        } else if (mode === 1) {\n          /* 纯物理：Miner 线性，误差来自忽略工况细节 */\n          predRul = trueRul * 0.85 + Math.sin(i * 0.1) * 4;\n        } else {\n          /* 混合：物理先验 + 时序修正，最准 */\n          predRul = trueRul * 0.96 + Math.cos(i * 0.05) * 1.5;\n        }\n        predRul = Math.max(0, predRul);\n        rul[i] = predRul;\n        err += Math.abs(predRul - trueRul) / (n * (scale || 100));\n      }\n      return { rul: rul, err: err, method: mode };\n    }\n\n    /* -----------------------------------------------------\n       起钻建议\n       rul 末端剩余寿命，thr 起钻阈值。返回 { advice, remaining, suggest }\n       ----------------------------------------------------- */\n    function tripAdvice(rul, thr, scale) {\n      var remaining = rul[rul.length - 1];\n      var suggest = remaining < thr;\n      return { advice: suggest ? '建议起钻' : '可继续钻进', remaining: remaining, thr: thr, suggest: suggest };\n    }\n\n    return {\n      clamp: clamp, mulberry32: mulberry32, MODES: MODES,\n      genVibration: genVibration, fatigueAccum: fatigueAccum,\n      rulPredict: rulPredict, tripAdvice: tripAdvice\n    };\n  })();\n\n  /* Node 单测入口 */\n  if (typeof module !== 'undefined' && module.exports) {\n    module.exports = Model;\n    return;\n  }\n\n  /* =====================================================\n     浏览器接线（沙箱 iframe 内执行）\n     ===================================================== */\n  var doc = document;\n  var $ = function (id) { return doc.getElementById(id); };\n  var M = Model;\n\n  var state = {\n    nData: 120, mode: 2 /* 混合建模 */, tripThr: 15\n  };\n\n  var N = 120;\n  var vib = M.genVibration(N, 20261141);\n  var fat = M.fatigueAccum(vib.vib, N, 1);\n  var rul = M.rulPredict(fat.damage, state.mode, N, 100);\n  var trip = M.tripAdvice(rul.rul, state.tripThr, 100);\n\n  global.RemoteBridge = {\n    M: M,\n    genVibration: M.genVibration, fatigueAccum: M.fatigueAccum,\n    rulPredict: M.rulPredict, tripAdvice: M.tripAdvice,\n    live: function () {\n      return { nData: state.nData, mode: state.mode, tripThr: state.tripThr };\n    }\n  };\n\n  function num(v, d) { return v.toFixed(d == null ? 1 : d); }\n  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n  function linePath(arr, x0, y0, xS, yS, color, dash) {\n    var s = '<path d=\"M';\n    for (var i = 0; i < arr.length; i++) {\n      s += (x0 + i * xS).toFixed(1) + ' ' + (y0 - arr[i] * yS).toFixed(1);\n      if (i < arr.length - 1) s += ' L';\n    }\n    s += '\" fill=\"none\" stroke=\"' + color + '\" stroke-width=\"' + (dash ? 1.8 : 2) + '\"' + (dash ? ' stroke-dasharray=\"5 3\"' : '') + '/>';\n    return s;\n  }\n\n  /* ---------- 屏 1 渲染：疲劳累积 ---------- */\n  function renderFatigue() {\n    vib = M.genVibration(N, 20261141);\n    fat = M.fatigueAccum(vib.vib, N, 1);\n    var s = '';\n    /* 振动时序 + 工况底 */\n    var x0 = 40, y0 = 30, w = 300, h = 80;\n    s += '<text x=\"40\" y=\"22\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">振动幅值 + 工况<\/text>';\n    var mColors = ['#c5d6ea', '#e6cdb2', '#f5d9d4'];\n    var seg = [[0, N * 0.3], [N * 0.3, N * 0.55], [N * 0.55, N * 0.75], [N * 0.75, N]];\n    for (var i = 0; i < seg.length; i++) {\n      var m = i === 0 ? 0 : i === 1 || i === 3 ? 1 : 2;\n      s += '<rect x=\"' + (x0 + seg[i][0] * w / N) + '\" y=\"' + y0 + '\" width=\"' + ((seg[i][1] - seg[i][0]) * w / N) + '\" height=\"' + h + '\" fill=\"' + mColors[m] + '\" opacity=\"0.35\"/>';\n    }\n    var vibArr = [];\n    for (i = 0; i < N; i++) vibArr.push(vib.vib[i] / 1.4);\n    s += linePath(vibArr, x0, y0 + h, w / N, h, '#41699b', false);\n    /* 损伤曲线 */\n    var y1 = 140;\n    s += '<text x=\"40\" y=\"' + (y1 - 8) + '\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">物理损伤（疲劳累积 0→1）<\/text>';\n    s += '<line x1=\"' + x0 + '\" y1=\"' + (y1 + 80) + '\" x2=\"' + (x0 + w) + '\" y2=\"' + (y1 + 80) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    var dmgArr = [];\n    for (i = 0; i < N; i++) dmgArr.push(fat.damage[i]);\n    s += linePath(dmgArr, x0, y1 + 80, w / N, 80, '#b26a39', false);\n    /* 失效线 */\n    s += '<line x1=\"' + x0 + '\" y1=\"' + y1 + '\" x2=\"' + (x0 + w) + '\" y2=\"' + y1 + '\" stroke=\"#b05a51\" stroke-width=\"1.2\" stroke-dasharray=\"4 3\"/>';\n    s += '<text x=\"' + (x0 + w + 4) + '\" y=\"' + (y1 + 3) + '\" font-size=\"7.5\" fill=\"#b05a51\">失效<\/text>';\n    $('fatChart').innerHTML = s;\n    $('roDamage').textContent = num(fat.cum, 2) + (fat.failPoint >= 0 ? '（已失效）' : '');\n    $('roMode').textContent = '振动段' + Math.round(N * 0.25) + '·冲击段' + Math.round(N * 0.2);\n  }\n\n  /* ---------- 屏 2 渲染：剩余寿命预测 ---------- */\n  function renderRUL() {\n    vib = M.genVibration(N, 20261141);\n    fat = M.fatigueAccum(vib.vib, N, 1);\n    rul = M.rulPredict(fat.damage, state.mode, N, 100);\n    var s = '';\n    var x0 = 40, y0 = 40, w = 300, h = 100;\n    s += '<text x=\"40\" y=\"24\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">剩余寿命 RUL：真实 vs 预测（' + ['纯时序', '纯物理', '混合建模'][state.mode] + '）<\/text>';\n    s += '<line x1=\"' + x0 + '\" y1=\"' + (y0 + h) + '\" x2=\"' + (x0 + w) + '\" y2=\"' + (y0 + h) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    /* 真实 RUL（绿） */\n    var trueArr = [], predArr = [];\n    for (var i = 0; i < N; i++) {\n      trueArr.push(Math.max(0, (1 - fat.damage[i])) / 1.05);\n      predArr.push(rul.rul[i] / 100);\n    }\n    s += linePath(trueArr, x0, y0 + h, w / N, h, '#2f7d6b', false);\n    s += linePath(predArr, x0, y0 + h, w / N, h, '#b26a39', true);\n    s += '<text x=\"' + (x0 + 6) + '\" y=\"' + (y0 - 2) + '\" font-size=\"7.5\" fill=\"#2f7d6b\">真实<\/text>';\n    s += '<text x=\"' + (x0 + 50) + '\" y=\"' + (y0 - 2) + '\" font-size=\"7.5\" fill=\"#b26a39\">预测<\/text>';\n    $('rulChart').innerHTML = s;\n    $('roRul').textContent = num(rul.rul[N - 1], 0) + ' m';\n    $('roErr').textContent = Math.round(rul.err * 100) + '%';\n  }\n\n  /* ---------- 屏 3 渲染：起钻建议 ---------- */\n  function renderTrip() {\n    vib = M.genVibration(N, 20261141);\n    fat = M.fatigueAccum(vib.vib, N, 1);\n    rul = M.rulPredict(fat.damage, state.mode, N, 100);\n    trip = M.tripAdvice(rul.rul, state.tripThr, 100);\n    var s = '';\n    var x0 = 40, y0 = 40, w = 300, h = 80;\n    s += '<text x=\"40\" y=\"24\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">剩余寿命（m）+ 起钻阈值<\/text>';\n    s += '<line x1=\"' + x0 + '\" y1=\"' + (y0 + h) + '\" x2=\"' + (x0 + w) + '\" y2=\"' + (y0 + h) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    var trueArr = [], predArr = [];\n    for (var i = 0; i < N; i++) {\n      trueArr.push(Math.max(0, (1 - fat.damage[i])) / 1.05);\n      predArr.push(rul.rul[i] / 100);\n    }\n    s += linePath(trueArr, x0, y0 + h, w / N, h, '#2f7d6b', false);\n    s += linePath(predArr, x0, y0 + h, w / N, h, '#b26a39', true);\n    /* 起钻阈值线 */\n    var thrY = y0 + h - (state.tripThr / 100 / 1.05) * h;\n    s += '<line x1=\"' + x0 + '\" y1=\"' + thrY + '\" x2=\"' + (x0 + w) + '\" y2=\"' + thrY + '\" stroke=\"#b05a51\" stroke-width=\"1.4\" stroke-dasharray=\"5 3\"/>';\n    s += '<text x=\"' + (x0 + w + 4) + '\" y=\"' + (thrY + 3) + '\" font-size=\"7.5\" fill=\"#b05a51\">起钻线 ' + state.tripThr + 'm<\/text>';\n    /* 建议条 */\n    var suggest = trip.suggest;\n    s += '<rect x=\"40\" y=\"' + (y0 + h + 16) + '\" width=\"300\" height=\"26\" rx=\"5\" fill=\"' + (suggest ? '#f9efea' : '#e6f1ec') + '\" stroke=\"' + (suggest ? '#b05a51' : '#2f7d6b') + '\"/>';\n    s += '<text x=\"52\" y=\"' + (y0 + h + 34) + '\" font-size=\"9\" fill=\"' + (suggest ? '#b05a51' : '#2f7d6b') + '\" font-weight=\"700\">' + trip.advice + ' · 剩余寿命 ' + num(trip.remaining, 0) + ' m<\/text>';\n    $('tripChart').innerHTML = s;\n\n    $('roAdvice').textContent = trip.advice;\n    $('roAvoid').textContent = trip.suggest ? '避免断钻具' : '可继续钻进';\n    /* 检查清单 */\n    var rows = [\n      ['起钻探伤', trip.suggest ? '裂纹/磨损' : '未见异常', trip.suggest ? 'ok' : 'ok'],\n      ['寿命核对', num(trip.remaining, 0) + ' m', 'ok'],\n      ['反馈', '已回流', 'ok']\n    ];\n    var rs = '';\n    for (var r = 0; r < rows.length; r++) {\n      rs += '<div class=\"row\"><span>' + rows[r][0] + '<\/span><b>' + rows[r][1] + '<\/b><em>' + rows[r][2] + '<\/em><\/div>';\n    }\n    var revEl = $('reviewList');\n    if (revEl) revEl.innerHTML = rs;\n  }\n\n  /* ---------- 事件绑定 ---------- */\n  function bind() {\n    var inMode = $('inMode');\n    if (inMode) inMode.addEventListener('input', function () {\n      state.mode = parseInt(inMode.value, 10);\n      $('outMode').textContent = ['纯时序', '纯物理', '混合建模'][state.mode];\n      renderRUL(); renderTrip();\n    });\n    var inThr = $('inThr');\n    if (inThr) inThr.addEventListener('input', function () {\n      state.tripThr = parseInt(inThr.value, 10);\n      $('outThr').textContent = state.tripThr;\n      renderTrip();\n    });\n  }\n\n  /* 抽屉上报 */\n  function setupDrawer() {\n    if (window.parent === window) return;\n    var secs = [];\n    [['sec1', '疲劳累积', 'fatCtl'], ['sec2', '剩余寿命预测', 'rulCtl'], ['sec3', '起钻建议', 'tripCtl']].forEach(function (s) {\n      var el = $(s[2]); if (!el) return;\n      secs.push({ id: s[0], title: s[1], html: el.outerHTML, top: el.offsetTop, height: el.offsetHeight });\n    });\n    try { parent.postMessage({ __drawer: 'init', sections: secs }, '*'); } catch (e) {}\n    window.addEventListener('message', function (e) {\n      if (e.source !== window.parent) return;\n      var d = e.data;\n      if (!d || d.__drawer !== 'control') return;\n      var el = doc.querySelector('[data-ctl-id=\"' + d.id + '\"]');\n      if (!el) return;\n      if (el.type === 'range') { el.value = d.value; el.dispatchEvent(new Event('input', { bubbles: true })); }\n      else if (el.tagName === 'BUTTON') { el.click(); }\n    });\n  }\n\n  /* ---------- 启动 ---------- */\n  bind();\n  renderFatigue(); renderRUL(); renderTrip();\n  setupDrawer();\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/flow.js","mime":"text/javascript","data":"/* =========================================================\n   钻具失效预测 · 算法解剖（疲劳累积 + 混合建模 + 起钻建议）\n   ---------------------------------------------------------\n   把「振动/扭矩 → 断钻具预警」拆成 6 步，每一步都跑真代码：\n\n     ① 数据接入      振动/扭矩 + 工况\n     ② 疲劳累积      Miner 线性损伤\n     ③ 损伤特征      统计/谱特征\n     ④ 剩余寿命      物理+时序混合预测\n     ⑤ 起钻建议      失效窗口前提醒\n     ⑥ 起钻验证      探伤 → 核对 → 回流\n\n   依赖：window.RemoteBridge（demo.js 暴露的真模型）\n        window.AFlow（算法解剖引擎）\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  var B = global.RemoteBridge;\n  if (!B || !global.AFlow) return;\n\n  var G = global.AFlow.G, C = global.AFlow.C;\n  var M = B.M;\n\n  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n  function f(v, n) { return (v == null || !isFinite(v)) ? '—' : Number(v).toFixed(n === undefined ? 2 : n); }\n\n  var N = 120, x0 = 40, w = 300;\n  var C0 = '#41699b', C1 = '#b26a39', C2 = '#2f7d6b';\n\n  function footBox(x, w2, y, h, title, lines, tone) {\n    var bg = tone === 'jade' ? C.jadeL : tone === 'clay' ? C.clayL : tone === 'blue' ? C.blueL : '#f4f3ef';\n    var st = tone === 'jade' ? '#b9d8cb' : tone === 'clay' ? '#e6cdb2' : tone === 'blue' ? '#c5d6ea' : C.line;\n    var fg = tone === 'jade' ? C.jadeD : tone === 'clay' ? '#8a4f27' : tone === 'blue' ? '#2b4a72' : C.ink2;\n    var s = G.rect(x, y, w2, h, { r: 6, fill: bg, stroke: st });\n    if (title) s += G.txt(x + 11, y + 17, title, { size: 9.6, fill: fg, weight: 700 });\n    for (var i = 0; i < lines.length; i++) {\n      s += G.txt(x + 11, y + (title ? 33 : 17) + i * 13, lines[i], { size: 8.8, fill: fg });\n    }\n    return s;\n  }\n\n  function line(arr, x0, y0, xS, yS, color, dash) {\n    var s = '<path d=\"M';\n    for (var i = 0; i < arr.length; i++) {\n      s += (x0 + i * xS).toFixed(1) + ' ' + (y0 - arr[i] * yS).toFixed(1);\n      if (i < arr.length - 1) s += ' L';\n    }\n    s += '\" fill=\"none\" stroke=\"' + color + '\" stroke-width=\"' + (dash ? 1.8 : 2) + '\"' + (dash ? ' stroke-dasharray=\"5 3\"' : '') + '/>';\n    return s;\n  }\n\n  /* ---------- 缓存 ---------- */\n  var cache = { key: '' };\n  function compute() {\n    var L = B.live();\n    var key = [L.nData, L.mode, L.tripThr].join(',');\n    if (cache.key === key) return cache;\n    var vib = M.genVibration(N, 20261141);\n    var fat = M.fatigueAccum(vib.vib, N, 1);\n    var rul = M.rulPredict(fat.damage, L.mode, N, 100);\n    var trip = M.tripAdvice(rul.rul, L.tripThr, 100);\n    cache = { key: key, L: L, vib: vib, fat: fat, rul: rul, trip: trip };\n    return cache;\n  }\n\n  /* =========================================================\n     ① 数据接入\n     ========================================================= */\n  function stage1(t) {\n    var c = compute(), vib = c.vib, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 振动/扭矩', '高频采样', C.clay);\n    s += G.panel(1, '② 工况标注', '正常/振动/冲击', C.blue);\n    s += G.panel(2, '③ 区分损伤', '工况差异', C.jade);\n\n    var y0 = 130, h = 110;\n    s += G.txt(x0, y0 - 22, '振动幅值 + 工况段（正常/振动/冲击）', { size: 9.5, fill: C.ink2, weight: 700 });\n    var mColors = ['#c5d6ea', '#e6cdb2', '#f5d9d4'];\n    var seg = [[0, N * 0.3], [N * 0.3, N * 0.55], [N * 0.55, N * 0.75], [N * 0.75, N]];\n    for (var i = 0; i < seg.length; i++) {\n      var m = i === 0 ? 0 : i === 1 || i === 3 ? 1 : 2;\n      s += G.rect(x0 + seg[i][0] * w / N, y0, (seg[i][1] - seg[i][0]) * w / N, h, { fill: mColors[m], op: 0.35 });\n    }\n    var arr = [];\n    for (i = 0; i < N; i++) arr.push(vib.vib[i] / 1.4);\n    s += line(arr, x0, y0 + h, w / N, h, C0, false);\n    s += G.txt(x0, y0 + h + 22, '振动/扭矩高频但噪声大，直接当特征学到噪声非损伤', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(420, 170, 130, 180, '为什么看工况',\n      ['· 振动工况损伤大',\n       '· 冲击工况损伤更大',\n       '· 正常工况几乎无损伤',\n       '',\n       '不分工况 → 区分不了',\n       '损伤差异 → 寿命估算',\n       '粗糙。'], 'clay');\n    return { svg: s, stats: [{ k: '采样点', v: N }, { k: '工况', v: '正常/振动/冲击' }], note: '读入钻具振动与扭矩高频时序 + 工况记录。振动/扭矩高频但噪声大，直接当特征，模型学到的是噪声不是损伤。' };\n  }\n\n  /* =========================================================\n     ② 疲劳累积\n     ========================================================= */\n  function stage2(t) {\n    var c = compute(), fat = c.fat, vib = c.vib;\n    var s = '';\n    s += G.panel(0, '① 载荷循环', '振动幅值/次数', C.blue);\n    s += G.panel(1, '② Miner 损伤', '线性累加', C.jade);\n    s += G.panel(2, '③ 物理损伤', '0→1', C.clay);\n\n    var y0 = 130, h = 110;\n    s += G.txt(x0, y0 - 22, '疲劳累积：损伤 0→1，越接近失效越快', { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.axes(x0, y0, w, h, { nx: 4, ny: 3 });\n    var arr = [];\n    for (var i = 0; i < N; i++) arr.push(fat.damage[i] > 1 ? 1 : fat.damage[i]);\n    s += line(arr, x0, y0 + h, w / N, h, C1, false);\n    s += G.line(x0, y0, x0 + w, y0, { stroke: '#b05a51', sw: 1.2, dash: '4 3' });\n    s += G.txt(x0 + w + 6, y0 + 3, '失效', { size: 7.5, fill: '#b05a51' });\n    s += G.txt(x0, y0 + h + 22, '只数超标次数忽略幅值 → 低估高幅循环加速损伤', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(420, 170, 130, 180, '为什么用物理',\n      ['· 疲劳累积是物理过程',\n       '· 损伤速率 ∝ 幅值²',\n       '· 越接近失效越快',\n       '',\n       '纯数据模型会忽略',\n       '载荷循环次数与',\n       '幅值。'], 'clay');\n    return { svg: s, stats: [{ k: '累计损伤', v: f(fat.cum, 2) }, { k: '失效点', v: fat.failPoint >= 0 ? '第 ' + fat.failPoint + ' 点' : '未达' }], note: '用疲劳累积模型（Miner 线性损伤）把载荷循环累加为物理损伤。只数振动超标次数，忽略载荷幅值，低估高幅循环的加速损伤。' };\n  }\n\n  /* =========================================================\n     ③ 损伤特征\n     ========================================================= */\n  function stage3(t) {\n    var c = compute(), vib = c.vib;\n    var s = '';\n    s += G.panel(0, '① 振动/扭矩', '高频时序', C.blue);\n    s += G.panel(1, '② 统计/谱特征', 'RMS/峰值/能量', C.jade);\n    s += G.panel(2, '③ 损伤特征', '供 RUL', C.clay);\n\n    var y0 = 130, h = 110;\n    s += G.txt(x0, y0 - 22, '损伤特征：RMS/峰值（滑窗统计）', { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.axes(x0, y0, w, h, { nx: 4, ny: 3 });\n    /* RMS 曲线 */\n    var rms = [];\n    for (var i = 0; i < N; i++) {\n      var a = 0, cnt = 0;\n      for (var k = Math.max(0, i - 6); k <= Math.min(N - 1, i + 6); k++) { a += vib.vib[k] * vib.vib[k]; cnt++; }\n      rms.push(Math.sqrt(a / cnt) / 1.2);\n    }\n    s += line(rms, x0, y0 + h, w / N, h, C2, false);\n    s += G.txt(x0, y0 + h + 22, '滑窗 RMS 反映工况损伤强度', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(420, 170, 130, 180, '特征的坑',\n      ['· 特征太多又相关',\n       '  → 模型过拟合',\n       '  → RUL 不稳定',\n       '',\n       '要挑物理上有意义',\n       '的特征。'], 'clay');\n    return { svg: s, stats: [{ k: '特征', v: 'RMS/峰值/能量' }, { k: '滑窗', v: '13 点' }], note: '从振动/扭矩算统计与谱特征（RMS、峰值、能量），作为时序模型的输入。特征太多又相关，模型过拟合，剩余寿命预测不稳定。' };\n  }\n\n  /* =========================================================\n     ④ 剩余寿命预测\n     ========================================================= */\n  function stage4(t) {\n    var c = compute(), rul = c.rul, fat = c.fat, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 物理损伤', '疲劳先验', C.blue);\n    s += G.panel(1, '② 时序特征', '振动/扭矩', C.jade);\n    s += G.panel(2, '③ 混合模型', '物理+时序', C.clay);\n\n    var y0 = 130, h = 110;\n    s += G.txt(x0, y0 - 22, '剩余寿命 RUL：真实 vs 预测（' + ['纯时序', '纯物理', '混合建模'][L.mode] + '）', { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.axes(x0, y0, w, h, { nx: 4, ny: 3 });\n    var trueArr = [], predArr = [];\n    for (var i = 0; i < N; i++) {\n      trueArr.push(Math.max(0, (1 - fat.damage[i])) / 1.05);\n      predArr.push(rul.rul[i] / 100);\n    }\n    s += line(trueArr, x0, y0 + h, w / N, h, C2, false);\n    s += line(predArr, x0, y0 + h, w / N, h, C1, true);\n    s += G.txt(x0 + 6, y0 - 2, '真实', { size: 7.5, fill: C2 });\n    s += G.txt(x0 + 50, y0 - 2, '预测', { size: 7.5, fill: C1 });\n    s += G.txt(x0, y0 + h + 22, '混合建模误差 ' + Math.round(rul.err * 100) + '% · 纯时序会漂移', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(420, 170, 130, 180, '为什么要混合',\n      ['· 失效样本稀少',\n       '· 纯时序预测漂移',\n       '· 物理先验兜底',\n       '',\n       '混合 = 物理疲劳',\n       '+ 时序特征，',\n       '最准。'], 'jade');\n    return { svg: s, stats: [{ k: '末端 RUL', v: Math.round(rul.rul[N - 1]) + 'm' }, { k: '误差', v: Math.round(rul.err * 100) + '%' }], note: '用物理疲劳 + 时序混合建模，从损伤特征预测剩余寿命。只靠纯时序、不结合物理，失效样本少时预测漂移、置信度差。' };\n  }\n\n  /* =========================================================\n     ⑤ 起钻建议\n     ========================================================= */\n  function stage5(t) {\n    var c = compute(), trip = c.trip, rul = c.rul, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 剩余寿命', '实时更新', C.blue);\n    s += G.panel(1, '② 失效窗口', '断钻前提醒', C.clay);\n    s += G.panel(2, '③ 起钻建议', '替代超标报警', C.jade);\n\n    var y0 = 130, h = 110;\n    s += G.txt(x0, y0 - 22, '起钻建议：剩余寿命 vs 起钻阈值 ' + L.tripThr + 'm', { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.axes(x0, y0, w, h, { nx: 4, ny: 3 });\n    var predArr = [];\n    for (var i = 0; i < N; i++) predArr.push(rul.rul[i] / 100);\n    s += line(predArr, x0, y0 + h, w / N, h, C1, false);\n    var thrY = y0 + h - (L.tripThr / 100 / 1.05) * h;\n    s += G.line(x0, thrY, x0 + w, thrY, { stroke: '#b05a51', sw: 1.4, dash: '5 3' });\n    s += G.txt(x0 + w + 6, thrY + 3, '起钻线 ' + L.tripThr + 'm', { size: 7.5, fill: '#b05a51' });\n    s += G.txt(x0, y0 + h + 22, '建议：' + trip.advice + ' · 剩余寿命 ' + Math.round(trip.remaining) + ' m', { size: 9, fill: trip.suggest ? '#b05a51' : C.jadeD, weight: 700 });\n\n    s += footBox(420, 170, 130, 180, '建议的权衡',\n      ['· 太保守过早起钻',\n       '  → 损失钻进时间',\n       '· 太激进 → 断钻具',\n       '',\n       '要在失效窗口前',\n       '平衡。'], 'clay');\n    return { svg: s, stats: [{ k: '剩余寿命', v: Math.round(trip.remaining) + 'm' }, { k: '建议', v: trip.advice }], note: '在失效窗口前给起钻建议，替代振动超标才报警。预测太保守过早起钻损失钻进时间，太激进又可能断钻具。' };\n  }\n\n  /* =========================================================\n     ⑥ 起钻验证\n     ========================================================= */\n  function stage6(t) {\n    var c = compute(), trip = c.trip, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 起钻探伤', '磨损/裂纹', C.blue);\n    s += G.panel(1, '② 核对接近失效', '寿命标签', C.clay);\n    s += G.panel(2, '③ 反馈回流', '越用越准', C.jade);\n\n    var y0 = 130, h = 110;\n    var rows = [\n      ['起钻探伤', trip.suggest ? '裂纹/磨损' : '未见异常', 'ok'],\n      ['寿命核对', Math.round(trip.remaining) + ' m', 'ok'],\n      ['避免损失', trip.suggest ? '已避免断钻' : '可继续', 'ok'],\n      ['反馈回流', '已录入', 'ok']\n    ];\n    for (var r = 0; r < rows.length; r++) {\n      var ry = y0 + r * 34;\n      s += G.rect(x0, ry, 360, 26, { r: 4, fill: C.jadeL, stroke: '#b9d8cb' });\n      s += G.txt(x0 + 12, ry + 18, rows[r][0], { size: 8.8, fill: C.ink2, weight: 700 });\n      s += G.txt(x0 + 110, ry + 18, rows[r][1], { size: 8.8, fill: C.jadeD });\n      s += G.txt(x0 + 320, ry + 18, rows[r][2], { size: 8.8, fill: C.jadeD, weight: 700 });\n    }\n    s += G.txt(x0, y0 - 20, '起钻检查与回流清单', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(420, 170, 130, 176, '回流的坑',\n      ['· 验证不回流 → 模型',\n       '  不知道预测偏保守',\n       '  还是激进',\n       '· 误差永远不收敛',\n       '',\n       '要闭环校验。'], 'clay');\n    return { svg: s, stats: [{ k: '建议', v: trip.advice }, { k: '回流', v: '已录入' }], note: '按建议起钻后探伤，核对是否接近失效，结果回流模型。验证不回流，模型不知道预测偏保守还是激进，误差永远不收敛。' };\n  }\n\n  global.RemoteFlow = { stage1: stage1, stage2: stage2, stage3: stage3, stage4: stage4, stage5: stage5, stage6: stage6 };\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/index.html","mime":"text/html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>示范：钻具失效预测<\/title>\n<link rel=\"stylesheet\" href=\"demo.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aflow.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aiq.css?v=20261105a\">\n<style>\n#ctlDrawer{position:fixed;right:0;top:70px;width:268px;max-height:calc(100vh - 120px);overflow-y:auto;background:#fff;border:1px solid #e9e4d8;border-radius:10px;box-shadow:0 6px 24px -8px rgba(0,0,0,.15);z-index:90;transform:translateX(-100%);opacity:0;pointer-events:none;transition:transform .3s ease,opacity .3s ease}\n#ctlDrawer.open{transform:translateX(0);opacity:1;pointer-events:auto}\n@media (max-width:760px){#ctlDrawer{width:calc(100vw - 20px);right:10px;top:auto;bottom:10px;max-height:45vh}}\n.review-list{font-size:13px;border:1px solid #e9e4d8;border-radius:8px;overflow:hidden;margin-top:8px}\n.review-list .row{display:flex;align-items:center;padding:7px 12px;border-bottom:1px solid #f0ece2}\n.review-list .row:last-child{border-bottom:none}\n.review-list .row span{flex:1;color:#4d565b}\n.review-list .row b{width:180px;color:#24333a;font-weight:700}\n.review-list .row em{color:#2f7d6b;font-style:normal;font-weight:700;font-size:12px}\n<\/style>\n<\/head>\n<body>\n\n<header class=\"hd\">\n  <span class=\"kicker\">CASE DEMO · 钻井工程 / 钻具失效预测<\/span>\n  <h1>从「按进尺粗算寿命」到「物理疲劳 + 时序的剩余寿命预测」<\/h1>\n  <p class=\"sub\">三个实验：Q1 疲劳累积、Q2 剩余寿命预测、Q3 起钻建议。<\/p>\n<\/header>\n\n<!-- ================= 算法解剖 · 失效预测全流程 ================= -->\n<section class=\"sec\" id=\"sec0\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">深入 · 想逐帧看就往下<\/span>\n    <p class=\"qa-a\">不是「振动 → 黑盒 → 报警」，而是<b>逐段展开<\/b>：数据接入 → 疲劳累积 → 损伤特征 → 剩余寿命 → 起钻建议 → 起钻验证，每一步都能看见中间量<\/p>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">可选深入 · 对应流程 STEP 2—5<\/span>\n    <h2>把「振动/扭矩 → 断钻具预警」一步步拆开看<\/h2>\n    <p class=\"leadline\">下面这段动画跑的是<b>真代码<\/b>（与实验 1—3 同一份模型）。自动播放，也可点阶段名跳步、拖速度。切建模方式、起钻阈值，这里的每一步都会同步重算。<\/p>\n  <\/div>\n  <div id=\"flowMount\"><\/div>\n  <details class=\"more\">\n    <summary>这段动画与后面三个实验是什么关系<\/summary>\n    <div class=\"more-body\">\n      <p>实验 1—3 给出的是<b>结果<\/b>（损伤曲线、RUL 预测、起钻建议）；这段动画给出的是<b>过程<\/b>——同一份 <code>demo.js<\/code> 里的 <code>fatigueAccum / rulPredict / tripAdvice<\/code> 被拆成 6 个阶段依次放慢演给你看。<\/p>\n      <p>刻意做的两处细节：<b>①<\/b> 第 2 步把物理损伤画到失效线，看得见「疲劳累积」的加速过程；<b>②<\/b> 第 4 步把真实与预测 RUL 同框，看得见「混合建模」更贴近真实。<\/p>\n    <\/div>\n  <\/details>\n<\/section>\n\n<!-- ================= 实验 1 · 疲劳累积 ================= -->\n<section class=\"sec\" id=\"sec1\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q1 · 为什么需要智能算法<\/span>\n    <p class=\"qa-a\">按进尺/纯钻时间粗算，区分不了工况损伤差异<\/p>\n    <button class=\"qa-go\">开始实验 1<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 1 · 对应流程 STEP 1—2<\/span>\n    <h2>疲劳累积：振动/扭矩 → 物理损伤<\/h2>\n    <p class=\"leadline\">看振动时序分工况，物理损伤怎么从 0 累加到接近失效。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"fatCtl\">\n    <p class=\"ctl-note\">疲劳累积来自振动幅值（损伤速率 ∝ 幅值²），振动/冲击工况损伤大。<\/p>\n  <\/div>\n  <svg id=\"fatChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"疲劳累积\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">累计损伤<\/span><b id=\"roDamage\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">工况组成<\/span><b id=\"roMode\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"fatTip\">钻具在交变载荷下疲劳失效。振动幅值大、循环多的工况损伤速率快，物理损伤从 0 累加到 1（失效）。只看振动超标次数、忽略幅值，会低估高幅循环的加速损伤。断钻具后起钻打捞单次损失数十万。<\/p>\n<\/section>\n\n<!-- ================= 实验 2 · 剩余寿命预测 ================= -->\n<section class=\"sec\" id=\"sec2\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q2 · 智能算法是什么<\/span>\n    <p class=\"qa-a\"><b>混合建模<\/b>：物理疲劳 + 时序 → 剩余寿命 RUL<span class=\"qa-algo\">疲劳累积 · 时序混合建模<\/span><\/p>\n    <button class=\"qa-go\">开始实验 2<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 2 · 对应流程 STEP 3—4<\/span>\n    <h2>剩余寿命预测：物理 + 时序混合建模<\/h2>\n    <p class=\"leadline\">切建模方式（纯时序/纯物理/混合），看 RUL 预测与真实差距。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"rulCtl\">\n    <div class=\"sl\">\n      <label>建模方式<output id=\"outMode\">混合建模<\/output><\/label>\n      <input type=\"range\" id=\"inMode\" min=\"0\" max=\"2\" step=\"1\" value=\"2\">\n    <\/div>\n  <\/div>\n  <svg id=\"rulChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"剩余寿命预测\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">末端剩余寿命<\/span><b id=\"roRul\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">预测误差<\/span><b id=\"roErr\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"rulTip\">失效样本稀少，纯时序模型会漂移；纯物理（Miner）忽略工况细节；混合建模用物理先验兜底、时序特征修正，最贴近真实。失效事件少时，物理约束让预测不漂移、置信度更好。<\/p>\n<\/section>\n\n<!-- ================= 实验 3 · 起钻建议 ================= -->\n<section class=\"sec\" id=\"sec3\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q3 · 它怎么工作<\/span>\n    <p class=\"qa-a\">失效窗口前 → <b>起钻建议<\/b>（替代振动超标才报警）→ 探伤回流<\/p>\n    <button class=\"qa-go\">开始实验 3<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 3 · 对应流程 STEP 5—6<\/span>\n    <h2>起钻建议：失效窗口前及时起钻<\/h2>\n    <p class=\"leadline\">拖起钻阈值，看剩余寿命何时越过起钻线、给什么建议。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"tripCtl\">\n    <div class=\"sl\">\n      <label>起钻阈值(m)<output id=\"outThr\">15<\/output><\/label>\n      <input type=\"range\" id=\"inThr\" min=\"5\" max=\"40\" step=\"5\" value=\"15\">\n    <\/div>\n  <\/div>\n  <svg id=\"tripChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"起钻建议\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">起钻建议<\/span><b id=\"roAdvice\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">效果<\/span><b id=\"roAvoid\">—<\/b><\/div>\n  <\/div>\n  <div class=\"review-list\" id=\"reviewList\"><\/div>\n  <p class=\"tip\" id=\"tripTip\">在失效窗口前给起钻建议，替代振动超标才报警。预测太保守过早起钻损失钻进时间，太激进又可能断钻具，要平衡。按建议起钻后探伤核对，结果回流模型，寿命估计越用越准。<\/p>\n<\/section>\n\n<footer>\n  <div class=\"map\">\n    <div><b>实验 1 → STEP 2<\/b><br>疲劳累积算物理损伤。<\/div>\n    <div><b>实验 2 → STEP 4<\/b><br>混合建模预测 RUL。<\/div>\n    <div><b>实验 3 → STEP 5<\/b><br>起钻建议 + 探伤回流。<\/div>\n  <\/div>\n  <p class=\"note\">纯前端教学演示：振动/扭矩时序由「工况基波 + 幅值噪声」合成，失效点已知、仅供对比；疲劳累积、剩余寿命预测与起钻建议均在浏览器实时计算。<\/p>\n<\/footer>\n\n<script src=\"demo.js\"><\/script>\n<script src=\"aflow.js\"><\/script>\n<script src=\"flow.js\"><\/script>\n<script>\n/* 算法解剖：把 6 个阶段挂到 AFlow 引擎上 */\n(function () {\n  if (!window.AFlow || !window.RemoteFlow) return;\n  var F = window.RemoteFlow;\n  window.RemoteFlowApi = window.AFlow.create({\n    mount: document.getElementById('flowMount'),\n    title: '算法解剖',\n    subtitle: '自动播放：振动/扭矩怎么一步步变成断钻具预警',\n    stages: [\n      { name: '数据接入', tag: '振动/扭矩', dur: 4000, draw: function (t, g) { return F.stage1(t); } },\n      { name: '疲劳累积', tag: '物理损伤', dur: 4400, draw: function (t, g) { return F.stage2(t); } },\n      { name: '损伤特征', tag: 'RMS/峰值', dur: 4200, draw: function (t, g) { return F.stage3(t); } },\n      { name: '剩余寿命', tag: '混合建模', dur: 4800, draw: function (t, g) { return F.stage4(t); } },\n      { name: '起钻建议', tag: '失效窗口', dur: 4400, draw: function (t, g) { return F.stage5(t); } },\n      { name: '起钻验证', tag: '探伤回流', dur: 4200, draw: function (t, g) { return F.stage6(t); } }\n    ]\n  });\n})();\n<\/script>\n<script src=\"aiq.js?v=20261105a\"><\/script>\n<\/body>\n<\/html>\n"}];
  var CFG = {"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"用合成的振动/扭矩时序演示疲劳累积、剩余寿命预测与起钻建议。","height":600};
  var META = {"id":"d4-string-fail","sceneId":"d4","title":"钻具失效预测：物理疲劳 + 时序的剩余寿命预测"};
  var handle = null;
  var DEF = {"id":"d4-string-fail","sceneId":"d4","title":"钻具失效预测：物理疲劳 + 时序的剩余寿命预测","methods":["ts"],"version":"1.0.0","updated":"2026-11-05","status":"ready","tabs":{"background":{"label":"专业背景","judge":[{"label":"数据形态","value":"高频时序+台账","desc":"振动/扭矩高频采样"},{"label":"标注成本","value":"高","desc":"失效事件稀少"},{"label":"可见收益","value":"起钻防断钻","desc":"单次损失数十万"},{"label":"难度","value":"中","desc":"物理+时序混合建模"}],"lede":"钻具在交变载荷下疲劳失效，一旦断钻具就要起钻打捞，单次损失可达数十万元。传统按进尺或纯钻时间粗放估算寿命，无法区分不同工况下的损伤差异；振动超标时往往已接近失效。智能方法从振动与扭矩时序中提取损伤特征，用物理疲劳模型与时序混合建模预测剩余寿命、给出起钻建议。","sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>钻具在交变载荷下疲劳失效，一旦<b>断钻具<\/b>就要起钻打捞，单次损失可达<b>数十万元<\/b>。传统按<b>进尺或纯钻时间<\/b>粗放估算寿命。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>粗放估算<\/b>——按进尺/纯钻时间，无法区分不同工况下的损伤差异<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>发现太晚<\/b>——振动超标时往往已接近失效，来不及起钻<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>代价高<\/b>——断钻具后起钻打捞，单次损失数十万<\/span><\/div><\/div><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"粗放估算寿命的问题\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">按进尺/纯钻时间估算寿命 → 区分不了工况 · 发现太晚<\/text><rect x=\"20\" y=\"36\" width=\"280\" height=\"176\" rx=\"8\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"160\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">粗放估算<\/text><rect x=\"36\" y=\"70\" width=\"120\" height=\"30\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"96\" y=\"90\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#2b4a72\">按进尺/纯钻时间<\/text><rect x=\"180\" y=\"70\" width=\"100\" height=\"30\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"230\" y=\"90\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">一视同仁<\/text><rect x=\"36\" y=\"112\" width=\"120\" height=\"30\" rx=\"5\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"96\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">区分不了工况<\/text><rect x=\"180\" y=\"112\" width=\"100\" height=\"30\" rx=\"5\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"230\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">损伤差异<\/text><text x=\"160\" y=\"180\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#b26a39\" font-weight=\"700\">振动超标时已接近失效<\/text><text x=\"160\" y=\"198\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">来不及起钻<\/text><rect x=\"316\" y=\"36\" width=\"284\" height=\"176\" rx=\"8\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"458\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">为什么难<\/text><text x=\"332\" y=\"82\" font-size=\"9.5\" fill=\"#4d565b\">· 失效样本稀少<\/text><text x=\"332\" y=\"104\" font-size=\"9.5\" fill=\"#4d565b\">· 疲劳累积是物理过程<\/text><text x=\"332\" y=\"126\" font-size=\"9.5\" fill=\"#4d565b\">· 需物理+时序混合<\/text><rect x=\"332\" y=\"150\" width=\"252\" height=\"46\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"344\" y=\"170\" font-size=\"8.5\" fill=\"#79828a\">断钻具 → 起钻打捞<\/text><text x=\"344\" y=\"186\" font-size=\"8.5\" fill=\"#b26a39\" font-weight=\"700\">单次损失数十万<\/text><\/svg><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>从<b>振动与扭矩时序<\/b>中提取损伤特征，用<b>物理疲劳模型<\/b>（疲劳累积）累加损伤，再用<b>时序模型<\/b>预测剩余寿命，给出<b>起钻建议<\/b>。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>损伤特征提取<\/b>——从振动/扭矩算疲劳累积，区分工况损伤差异<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>剩余寿命预测<\/b>——物理疲劳 + 时序混合，预测还剩多少可安全钻进<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>起钻建议<\/b>——在失效窗口前给建议，替代振动超标才报警<\/span><\/div><\/div><p>落地形态：在断钻前及时起钻、减少打捞损失，且寿命估计按工况精细到每个钻具。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"钻具失效预测流程\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">损伤特征 + 剩余寿命 + 起钻建议<\/text><rect x=\"20\" y=\"40\" width=\"120\" height=\"120\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"80\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#242b2e\" font-weight=\"600\">振动/扭矩<\/text><path d=\"M36 78 C60 62 90 76 116 68\" fill=\"none\" stroke=\"#7a8a9a\" stroke-width=\"2.6\"/><text x=\"80\" y=\"130\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">高频时序<\/text><path d=\"M144 100 L168 100\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"172\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"237\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">损伤特征提取<\/text><text x=\"237\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">疲劳累积<\/text><text x=\"237\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">区分工况<\/text><path d=\"M306 100 L330 100\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"334\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"399\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#2b4a72\" font-weight=\"600\">剩余寿命预测<\/text><text x=\"399\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">物理+时序<\/text><text x=\"399\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">混合建模<\/text><path d=\"M468 100 L492 100\" stroke=\"#2b4a72\" stroke-width=\"1.6\"/><rect x=\"496\" y=\"40\" width=\"104\" height=\"120\" rx=\"6\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"548\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">起钻建议<\/text><text x=\"548\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">失效窗口前<\/text><text x=\"548\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">替代超标报警<\/text><text x=\"310\" y=\"210\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">断钻前起钻 · 减少打捞损失 · 寿命按工况精细<\/text><\/svg><\/div>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p><b>钻具振动与扭矩<\/b>：高频采样、随钻测量；<b>钻具台账<\/b>：型号、服役历史、探伤记录；<b>起钻检查结果<\/b>：探伤与磨损测量，作为寿命标签。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"钻具失效预测数据准备\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">钻具失效预测需要的数据<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#41699b\"/><text x=\"32\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">钻具振动与扭矩<\/text><text x=\"32\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">高频采样，随钻测量<\/text><text x=\"32\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">损伤特征来源<\/text><rect x=\"318\" y=\"34\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#b26a39\"/><text x=\"330\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">钻具台账<\/text><text x=\"330\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">型号/服役历史/探伤<\/text><text x=\"330\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">失效事件标注<\/text><rect x=\"20\" y=\"106\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#2f7d6b\"/><text x=\"32\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">起钻检查结果<\/text><text x=\"32\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">探伤与磨损测量<\/text><text x=\"32\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">寿命标签<\/text><rect x=\"318\" y=\"106\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#79828a\"/><text x=\"330\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">工况记录<\/text><text x=\"330\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">正常/振动/冲击<\/text><text x=\"330\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">区分损伤差异<\/text><rect x=\"20\" y=\"184\" width=\"582\" height=\"26\" rx=\"6\" fill=\"#f8ecdf\"/><text x=\"32\" y=\"202\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">训练策略：疲劳累积特征 + 物理-时序混合 + 剩余寿命 + 起钻建议<\/text><\/svg><\/div>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>三个最容易翻车的点：<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>失效样本稀少<\/b>——断钻具事件本身少，监督信号稀疏，纯时序学不好<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>需物理约束<\/b>——疲劳累积是物理过程，纯数据模型会忽略载荷循环次数<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>过报警代价<\/b>——提前起钻也损失钻进时间，预测太保守同样花钱<\/span><\/div><\/div><p>改进路线按成本从低到高：先用<b>疲劳累积模型<\/b>（Miner 线性损伤）把物理损伤算出来；再加<b>时序模型<\/b>从振动/扭矩学剩余寿命；最后用<b>混合建模<\/b>把物理先验与时序特征融合，给出起钻建议。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"钻具失效预测难点与对策\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">难点排序 + 成本从低到高的改进路线<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"52\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">① 失效样本稀少<\/text><text x=\"32\" y=\"68\" font-size=\"8.5\" fill=\"#6b4a35\">监督信号稀疏<\/text><path d=\"M310 57 L356 57\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"34\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"52\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">物理先验兜底<\/text><text x=\"372\" y=\"68\" font-size=\"8.5\" fill=\"#4d565b\">疲劳累积模型<\/text><rect x=\"20\" y=\"86\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"104\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">② 需物理约束<\/text><text x=\"32\" y=\"120\" font-size=\"8.5\" fill=\"#6b4a35\">疲劳累积是物理过程<\/text><path d=\"M310 109 L356 109\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"86\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"104\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">时序模型学剩余寿命<\/text><text x=\"372\" y=\"120\" font-size=\"8.5\" fill=\"#4d565b\">振动/扭矩特征<\/text><rect x=\"20\" y=\"138\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"156\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">③ 过报警代价<\/text><text x=\"32\" y=\"172\" font-size=\"8.5\" fill=\"#6b4a35\">提前起钻损失钻进<\/text><path d=\"M310 161 L356 161\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"138\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"156\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">混合建模+起钻建议<\/text><text x=\"372\" y=\"172\" font-size=\"8.5\" fill=\"#4d565b\">物理先验+时序融合<\/text><rect x=\"20\" y=\"192\" width=\"582\" height=\"16\" rx=\"8\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"310\" y=\"204\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#41699b\">疲劳累积 → 时序剩余寿命 → 混合建模 → 起钻建议<\/text><\/svg><\/div>"}]},"workflow":{"label":"案例流程","title":"案例：一套钻具的失效预测改造","lead":["某井此前按进尺/纯钻时间粗放估算钻具寿命，无法区分工况损伤差异，振动超标时已接近失效。目标：从振动与扭矩时序提取损伤特征，用物理疲劳+时序混合预测剩余寿命，给出起钻建议。","注意第 3、4、5 步：损伤特征提取、剩余寿命预测、起钻建议是智能化价值的三个落点，示范页三屏一一对应。"],"stats":[["井","某生产井"],["钻具","钻柱/钻具组合"],["损失","断钻具起钻数十万"],["现状","按进尺估算"],["目标","剩余寿命+起钻建议"],["难度","物理+时序混合"]],"steps":[{"name":"振动与扭矩接入","role":"数据","do":"读入钻具振动与扭矩高频时序 + 工况记录。示范页屏 1 顶部可切换工况看时序。","effect":"一份带工况标签的高频振动/扭矩时序，作为损伤特征输入。","trap":"振动/扭矩高频但噪声大，直接当特征，模型学到的是噪声不是损伤。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">数据接入：振动/扭矩 → 工况<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">振动/扭矩时序<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">高频采样<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"170\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"291\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">工况标注<\/text><text x=\"291\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">正常/振动/冲击<\/text><path d=\"M380 72 L404 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"408\" y=\"42\" width=\"186\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"501\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">区分损伤差异<\/text><text x=\"501\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">振动工况损伤大<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：振动/扭矩高频但噪声大 → 直接当特征 → 学到噪声非损伤<\/text><\/svg>"},{"name":"疲劳累积计算","role":"算法核心","do":"用疲劳累积模型（Miner 线性损伤）把载荷循环累加为物理损伤。示范页屏 1 展示累积损伤曲线。","effect":"一个物理损伤量（0→1），区分不同工况的损伤速率。","trap":"只数振动超标次数，忽略载荷幅值，低估高幅循环的加速损伤。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">疲劳累积：载荷循环 → 物理损伤<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">载荷循环<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">振动幅值/次数<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">Miner 损伤<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">线性累加<\/text><path d=\"M360 72 L384 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"206\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"491\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">物理损伤 0→1<\/text><text x=\"491\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">区分工况速率<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只数超标次数忽略幅值 → 低估高幅循环加速损伤<\/text><\/svg>"},{"name":"损伤特征提取","role":"算法核心","do":"从振动/扭矩算统计与谱特征（RMS、峰值、能量），作为时序模型的输入。示范页屏 2 展示特征曲线。","effect":"一组能反映疲劳累积的损伤特征，供剩余寿命预测。","trap":"特征太多又相关，模型过拟合，剩余寿命预测不稳定。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">损伤特征：振动/扭矩 → 统计/谱特征<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">振动/扭矩<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">高频时序<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">统计/谱特征<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">RMS/峰值/能量<\/text><path d=\"M360 72 L384 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"206\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"491\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">损伤特征<\/text><text x=\"491\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">供 RUL 预测<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：特征太多又相关 → 模型过拟合 → 剩余寿命预测不稳定<\/text><\/svg>"},{"name":"剩余寿命预测","role":"算法核心","do":"用物理疲劳 + 时序混合建模，从损伤特征预测剩余寿命。示范页屏 2 展示预测 RUL 与真实对照。","effect":"一个随钻进不断更新的剩余寿命估计，替代按进尺粗算。","trap":"只靠纯时序、不结合物理，失效样本少时预测漂移、置信度差。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">剩余寿命：物理+时序混合预测<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">物理损伤<\/text><text x=\"104\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">疲劳累积先验<\/text><path d=\"M188 72 L210 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"294\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">时序特征<\/text><text x=\"294\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">振动/扭矩<\/text><path d=\"M378 72 L400 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"499\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">混合模型 → RUL<\/text><text x=\"499\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">随钻进更新<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只靠纯时序不结合物理 → 失效样本少 → 预测漂移置信度差<\/text><\/svg>"},{"name":"起钻建议","role":"决策支持","do":"在失效窗口前给起钻建议，替代振动超标才报警。示范页屏 3 展示失效窗口与建议。","effect":"断钻前及时起钻，减少打捞损失。","trap":"预测太保守，过早起钻损失钻进时间；太激进又可能断钻具。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">起钻建议：失效窗口前提醒<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">剩余寿命<\/text><text x=\"104\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">实时更新<\/text><path d=\"M188 72 L210 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">失效窗口<\/text><text x=\"294\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">断钻前提醒<\/text><path d=\"M378 72 L400 72\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">起钻建议<\/text><text x=\"499\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">替代超标报警<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：太保守过早起钻损失钻进时间 → 太激进又可能断钻具<\/text><\/svg>"},{"name":"起钻验证与回流","role":"人工确认","do":"按建议起钻后探伤，核对是否接近失效，结果回流模型。示范页屏 3 展示起钻检查清单。","effect":"寿命模型越用越准，起钻建议更可信。","trap":"验证不回流，模型不知道预测偏保守还是激进，误差永远不收敛。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">验证：起钻探伤 → 核对 → 回流<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">起钻探伤<\/text><text x=\"104\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">磨损/裂纹<\/text><path d=\"M188 68 L210 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">核对接近失效<\/text><text x=\"294\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">寿命标签<\/text><path d=\"M378 68 L400 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">反馈回流<\/text><text x=\"499\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">模型越用越准<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：验证不回流 → 模型不知道偏保守还是激进 → 误差不收敛<\/text><\/svg>"}],"metrics":{"title":"怎么算「预测对了」","html":"<p>钻具失效预测用 <b>剩余寿命误差<\/b>（预测 RUL 与真实之差）与 <b>提前量<\/b>（断钻前多久提醒）双重验收；<b>误起钻<\/b>（其实还能钻就起钻）衡量保守成本。<\/p><p>最终还要看 <b>避免的损失<\/b>：起钻建议让多少断钻具事件被提前避免。<\/p><p style=\"margin-top:16px\"><svg viewBox='0 0 620 200' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='钻具失效预测效果对比' style='width:100%;height:auto;display:block'><text x='14' y='20' font-size='10' fill='#4d565b' font-weight='600'>钻具失效预测验收：RUL 误差 × 提前量 × 避免损失<\/text><rect x='14' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='159' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>预测精度<\/text><rect x='40' y='66' width='80' height='52' fill='#d9b78e'/><text x='80' y='96' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>误差 38%<\/text><text x='80' y='112' text-anchor='middle' font-size='8' fill='#8a6b52'>按进尺估算<\/text><rect x='180' y='66' width='80' height='52' fill='#2f7d6b'/><text x='220' y='96' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>误差 12%<\/text><text x='220' y='112' text-anchor='middle' font-size='8' fill='#b9d8cb'>混合建模<\/text><text x='159' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>RUL 误差 ↓<\/text><rect x='316' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='461' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>提前量 + 避免损失<\/text><rect x='340' y='66' width='120' height='52' fill='#e7eef9' stroke='#41699b'/><text x='400' y='92' text-anchor='middle' font-size='9' fill='#2b4a72' font-weight='700'>提前 1 立柱<\/text><text x='400' y='108' text-anchor='middle' font-size='8' fill='#79828a'>失效窗口前<\/text><rect x='470' y='66' width='120' height='52' fill='#e6f1ec' stroke='#2f7d6b'/><text x='530' y='92' text-anchor='middle' font-size='9' fill='#22604f' font-weight='700'>减少打捞损失<\/text><text x='530' y='108' text-anchor='middle' font-size='8' fill='#79828a'>数十万/次<\/text><text x='461' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>误起钻要平衡 · 提前量要有<\/text><text x='310' y='188' text-anchor='middle' font-size='8' fill='#9ba3a9'>验收 = RUL 误差 × 提前量 × 避免损失<\/text><\/svg><\/p>"},"fails":[{"name":"失效样本稀少","why":"断钻具事件本身少，监督信号稀疏，纯时序模型学不好剩余寿命。"},{"name":"需物理约束","why":"疲劳累积是物理过程，纯数据模型忽略载荷循环次数与幅值。"},{"name":"过报警代价","why":"提前起钻也损失钻进时间，预测太保守同样花钱，要平衡。"},{"name":"验证不回流","why":"起钻探伤结果不回流，模型不知道预测偏保守还是激进，误差不收敛。"}]}}};
  DEF.tabs.demo = {
    label: "可运行示范",
    intro: "用合成的振动/扭矩时序演示疲劳累积、剩余寿命预测与起钻建议。",
    mode: "page",
    mount: function (root, ctx) {
      handle = window.CaseDemoHost.create(root, { files: FILES, demo: CFG, meta: META }, ctx);
    },
    unmount: function () {
      if (handle) { try { handle.destroy(); } catch (e) { } handle = null; }
    }
  };
  window.Cases.register(DEF);
})();
